function appScrollTargets() {
  return Array.from(
    new Set(
      [
        document.querySelector(".content-area"),
        document.querySelector(".tab-panel.active"),
        document.querySelector(".tab-panel.active .request-labour-page"),
        document.querySelector(".tab-panel.active .request-labour-page-body"),
        document.querySelector(".tab-panel.active .company-dashboard-page"),
        document.querySelector(".tab-panel.active .attendance-page"),
        document.scrollingElement,
      ].filter(Boolean),
    ),
  );
}

function scrollAppToTop({ smooth = false } = {}) {
  const reduceMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
  const behavior = smooth && !reduceMotion ? "smooth" : "auto";
  const scroll = () => {
    appScrollTargets().forEach((target) => {
      target.scrollTop = 0;
      if (typeof target.scrollTo === "function") {
        target.scrollTo({ top: 0, behavior });
      }
    });
    window.scrollTo({ top: 0, behavior });
  };
  scroll();
  requestAnimationFrame(() => {
    scroll();
  });
}

function loadingSkeleton({ rows = 3, cards = 2, compact = false } = {}) {
  return Array.from({ length: cards }, () => {
    const rowHtml = Array.from(
      { length: rows },
      (_, index) =>
        `<span class="skeleton-line${index === 0 ? " wide" : ""}${compact ? " compact" : ""}"></span>`,
    ).join("");
    return `<div class="skeleton-card" aria-hidden="true">${rowHtml}</div>`;
  }).join("");
}

function setButtonLoading(button, isLoading, label = "Working") {
  if (!(button instanceof HTMLButtonElement)) return;
  if (isLoading) {
    if (!button.dataset.loadingOriginalHtml) {
      button.dataset.loadingOriginalHtml = button.innerHTML;
      button.dataset.loadingOriginalMinWidth = button.style.minWidth || "";
      if (button.offsetWidth) button.style.minWidth = `${button.offsetWidth}px`;
    }
    button.classList.add("is-loading");
    button.setAttribute("aria-busy", "true");
    button.disabled = true;
    button.innerHTML = `<span class="btn-spinner" aria-hidden="true"></span><span>${escapeHtml(label)}</span>`;
    return;
  }
  button.classList.remove("is-loading");
  button.removeAttribute("aria-busy");
  button.disabled = false;
  if (button.dataset.loadingOriginalHtml) {
    button.innerHTML = button.dataset.loadingOriginalHtml;
    button.style.minWidth = button.dataset.loadingOriginalMinWidth || "";
    delete button.dataset.loadingOriginalHtml;
    delete button.dataset.loadingOriginalMinWidth;
  }
}

function releaseButtonLoading(button) {
  if (!(button instanceof HTMLButtonElement)) return;
  window.setTimeout(() => {
    if (document.body.contains(button)) setButtonLoading(button, false);
  }, 450);
}

function hideWithMotion(element, afterHide, { remove = false } = {}) {
  if (!(element instanceof HTMLElement)) {
    if (typeof afterHide === "function") afterHide();
    return;
  }
  if (element.classList.contains("is-closing")) return;
  element.classList.add("is-closing");
  window.setTimeout(() => {
    element.classList.remove("is-closing");
    if (remove) {
      element.remove();
    } else {
      element.classList.add("hidden");
      element.setAttribute("aria-hidden", "true");
    }
    if (typeof afterHide === "function") afterHide();
  }, 170);
}

function showToast(msg) {
  let el = document.querySelector(".toast");
  if (!el) {
    el = document.createElement("div");
    el.className = "toast";
    document.body.appendChild(el);
  }
  el.textContent = msg;
  el.classList.add("show");
  setTimeout(() => el.classList.remove("show"), 2200);
}

// ─── Activity Log ─────────────────────────────────────────
let activityLog = loadActivity();

function loadActivity() {
  try {
    const saved = localStorage.getItem(ACTIVITY_KEY);
    if (saved) return JSON.parse(saved);
  } catch (_) {}
  return [];
}

function saveActivity() {
  try {
    localStorage.setItem(
      ACTIVITY_KEY,
      JSON.stringify(activityLog.slice(0, 50)),
    );
  } catch (_) {}
}

function logActivity(type, text) {
  activityLog.unshift({ type, text, ts: Date.now() });
  if (activityLog.length > 50) activityLog.pop();
  saveActivity();
}

function timeAgo(ts) {
  return formatRelativeTimestamp(ts);
}

const PROJECT_ACTIVITY_TYPES = Object.freeze({
  WORKER_SIGNED_IN: "worker_signed_in",
  WORKER_REPORTED_LATE: "worker_reported_late",
  WORKER_DID_NOT_ATTEND: "worker_did_not_attend",
  WORKER_ACCEPTED_OFFER: "worker_accepted_offer",
  WORKER_DECLINED_OFFER: "worker_declined_offer",
  WORKER_ASSIGNED: "worker_assigned",
  LABOUR_REQUIREMENT_FILLED: "labour_requirement_filled",
  REPLACEMENT_REQUESTED: "replacement_requested",
  REPLACEMENT_ASSIGNED: "replacement_assigned",
  ATTENDANCE_CONFIRMED: "attendance_confirmed",
  PROJECT_HEALTH_CHANGED: "project_health_changed",
  PROJECT_CREATED: "project_created",
  LABOUR_REQUEST_POSTED: "labour_request_posted",
  MATCHING_STARTED: "matching_started",
  PROJECT_UPDATED: "project_updated",
  QR_REGENERATED: "qr_regenerated",
  INVOICE_GENERATED: "invoice_generated",
  PROJECT_EXTENDED: "project_extended",
  PROJECT_COMPLETED: "project_completed",
});

const PROJECT_ACTIVITY_SEVERITIES = new Set([
  "info",
  "success",
  "warning",
  "critical",
]);

function normalizeProjectActivityRecord(record = {}, project = {}) {
  const timestamp =
    record.timestamp ||
    record.createdAt ||
    record.ts ||
    new Date().toISOString();
  const severity = PROJECT_ACTIVITY_SEVERITIES.has(record.severity)
    ? record.severity
    : "info";
  const title =
    record.title ||
    record.message ||
    record.text ||
    "Project activity";
  return {
    id: record.id || createId(),
    companyId: record.companyId || project.companyId || "",
    projectId: record.projectId || record.jobId || project.id || "",
    workerId: record.workerId || "",
    type: record.type || PROJECT_ACTIVITY_TYPES.PROJECT_UPDATED,
    title,
    description: record.description || record.message || record.text || "",
    timestamp,
    metadata:
      record.metadata && typeof record.metadata === "object"
        ? record.metadata
        : {},
    source: record.source || record.actor || record.actorName || "onsite",
    severity,
    message: record.message || title,
    field: record.field || "",
    before: record.before || "",
    after: record.after || "",
    createdAt: record.createdAt || timestamp,
    actor: record.actor || record.actorName || "",
  };
}

function createProjectActivityRecord(activity = {}, project = {}) {
  return normalizeProjectActivityRecord(
    {
      id: activity.id || createId(),
      timestamp: activity.timestamp || new Date().toISOString(),
      ...activity,
    },
    project,
  );
}

function projectActivityList(job) {
  if (!job) return [];
  if (!Array.isArray(job.projectActivity)) job.projectActivity = [];
  job.projectActivity = job.projectActivity
    .map((item) => normalizeProjectActivityRecord(item, job))
    .slice(0, 100);
  return job.projectActivity;
}

function syncProjectActivityStore(job, activity) {
  if (!job || !activity) return;
  if (!Array.isArray(state.projectActivities)) state.projectActivities = [];
  state.projectActivities = state.projectActivities.filter(
    (item) => item.id !== activity.id,
  );
  state.projectActivities.unshift(activity);
  state.projectActivities = state.projectActivities.slice(0, 500);
}

function projectActivityWorkerName(workerId, fallback = "") {
  if (!workerId) return fallback;
  return findWorker(workerId)?.name || fallback;
}

function addProjectActivity(job, activity = {}) {
  if (!job) return null;
  const dedupeKey =
    activity.dedupeKey ||
    activity.metadata?.dedupeKey ||
    `${activity.type || PROJECT_ACTIVITY_TYPES.PROJECT_UPDATED}:${activity.workerId || ""}:${activity.timestamp || activity.createdAt || ""}:${activity.title || ""}`;
  const list = projectActivityList(job);
  const exists = list.some(
    (item) =>
      item.id === activity.id ||
      item.metadata?.dedupeKey === dedupeKey,
  );
  if (exists) return null;
  const record = createProjectActivityRecord(
    {
      ...activity,
      companyId: activity.companyId || job.companyId || "",
      projectId: activity.projectId || job.id,
      metadata: {
        ...(activity.metadata || {}),
        dedupeKey,
      },
    },
    job,
  );
  list.unshift(record);
  job.projectActivity = list.slice(0, 100);
  syncProjectActivityStore(job, record);
  return record;
}

