function cloneRepeatLabourRequirements(job) {
  return uniqueLabourRequirements(labourRequirementsForJob(job)).map((req) => {
    const copied = { ...req, id: createId() };
    delete copied.labourSchedule;
    delete copied.overtimeAvailable;
    delete copied.overtimeRates;
    return copied;
  });
}

function applyRepeatProjectPreStartDraft(
  job,
  sourceLabourRequirements,
  copiedLabourRequirements,
  copiedRequirements,
) {
  const labourRequirementIds = new Map(
    sourceLabourRequirements.map((requirement, index) => [
      requirement.id,
      copiedLabourRequirements[index]?.id || "",
    ]),
  );
  draftPreStartRequirements = copiedRequirements
    .map((requirement) => {
      const audience = normalizeProjectRequirementAudience(
        requirement.audience,
      );
      const copiedAudience =
        audience.type === "labour_requirement"
          ? {
              ...audience,
              labourRequirementId:
                labourRequirementIds.get(audience.labourRequirementId) ||
                audience.labourRequirementId,
            }
          : audience;
      return normalizeDraftPreStartRequirement({
        ...requirement,
        documentId: createId(),
        audience: copiedAudience,
        createdAt: new Date().toISOString(),
        uploadedAt: new Date().toISOString(),
        versionHistory: [],
      });
    })
    .filter(Boolean);
  draftPreStartSetupStatus = draftPreStartRequirements.length
    ? "configured"
    : DRAFT_PRE_START_SETUP_STATUSES.has(job.preStartSetupStatus)
      ? job.preStartSetupStatus
      : "";
}

function setSelectValue(select, value) {
  if (!select) return;
  const stringValue = String(value || "");
  if (stringValue && !Array.from(select.options).some((option) => option.value === stringValue)) {
    select.appendChild(new Option(stringValue, stringValue));
  }
  select.value = stringValue;
}

function setInputValue(id, value) {
  const el = document.getElementById(id);
  if (el) el.value = value == null ? "" : String(value);
}

function setCheckboxValue(id, checked) {
  const el = document.getElementById(id);
  if (el) el.checked = !!checked;
}

function repeatProjectNoticeHTML(job) {
  return `<div id="repeatProjectNotice" class="repeat-project-notice">
    <div>
      <strong>Repeating ${escapeHtml(companyProjectTitle(job))}</strong>
      <span>Review copied site and labour details, then add fresh dates before submitting.</span>
    </div>
    <button class="secondary-btn" type="button" data-repeat-clear>Clear copied details</button>
  </div>`;
}

function applyRepeatProjectToForm(job) {
  if (!job) return;
  clearRepeatProjectTemplate();
  const sourceLabourRequirements = uniqueLabourRequirements(
    labourRequirementsForJob(job),
  );
  const copiedLabourRequirements = cloneRepeatLabourRequirements(job);
  const copiedPreStartRequirements = preStartDocumentsForJob(job).map(
    (doc) => ({
      ...doc,
      documentId: createId(),
      uploadedAt: new Date().toISOString(),
    }),
  );
  pendingRepeatProjectTemplate = {
    sourceProjectId: job.id,
    sourceProjectName: companyProjectTitle(job),
    preStartDocuments: copiedPreStartRequirements,
  };
  jobForm.reset();
  jobLocationPicker?.clear({ clearInput: true, emit: false });
  resetJobTradeRequirements();
  resetJobPhotos();
  currentJobPin = job.sitePin ? { ...job.sitePin } : { lat: null, lng: null };
  jobArrivalPointSource = currentJobHasEntrancePin() ? "existing" : "";
  currentJobPhotos = { ...(job.sitePhotos || {}) };
  currentJobPhotoMeta = { ...(job.sitePhotoMeta || {}) };
  setInputValue("jobNumber", "");
  setInputValue("projectName", `${companyProjectTitle(job)} repeat`);
  setSelectValue(document.getElementById("jobAssignmentType"), normalizeAssignmentType(job.assignmentType || job.jobType || "site_project"));
  if (job.locationData) {
    const restoredLocation = jobLocationPicker?.setSelectedLocation(job.locationData, {
      focus: false,
      emit: false,
    });
    if (!restoredLocation) jobLocationPicker?.setLegacyValue(job.location || "");
  } else {
    jobLocationPicker?.setLegacyValue(job.location || "");
  }
  const vehicle = job.vehicleArrangement || "not_required";
  const vehicleInput = document.querySelector(`input[name="jobVehicleArrangement"][value="${vehicle}"]`);
  if (vehicleInput) vehicleInput.checked = true;
  pendingTradeRequirements = copiedLabourRequirements;
  applyRepeatProjectPreStartDraft(
    job,
    sourceLabourRequirements,
    copiedLabourRequirements,
    copiedPreStartRequirements,
  );
  activeTradeRequirementId = "";
  tradeRequirementEditorOpen = !pendingTradeRequirements.length;
  clearTradeReqInputs();
  setInputValue("jobStart", jobStartDateOnly(job));
  setInputValue("jobEndDate", "");
  setCheckboxValue("jobNoFixedEndDate", !!job.noFixedEndDate);
  jobWizardShiftDefaultsInitialized = true;
  setInputValue("jobShiftStart", projectShiftStartValue(job));
  setInputValue("jobShiftFinish", job.shiftFinishTime || "");
  const days = new Set(normalizeWorkingDays(job.workingDays));
  document.querySelectorAll('input[name="jobWorkingDays"]').forEach((input) => {
    input.checked = days.has(input.value);
  });
  setInputValue("jobSiteAddress", job.siteAddress || "");
  jobArrivalPointAddress = currentJobHasEntrancePin()
    ? normalizedJobSiteAddress(job.siteAddress)
    : "";
  setInputValue("jobContactName", job.siteContact?.name || "");
  setInputValue("jobContactPhone", job.siteContact?.phone || "");
  setInputValue("jobArrivalInstructions", job.arrivalInstructions || "");
  setInputValue("jobParking", job.parking || "");
  setInputValue("jobPpe", job.ppe || "");
  setInputValue("jobGateAccess", job.gateAccess || "");
  setInputValue("attendanceManagerName", job.attendanceManager?.name || "");
  setInputValue("attendanceManagerEmail", job.attendanceManager?.email || "");
  setInputValue("attendanceManagerPhone", job.attendanceManager?.phone || "");
  const firstReq = pendingTradeRequirements[0] || {};
  const sourceFirstReq = sourceLabourRequirements[0] || {};
  const repeatedAccommodation = normalizedAccommodationState(
    accommodationArrangementFor(firstReq) ? firstReq : job,
  );
  setCheckboxValue("jobAccommodationPaid", repeatedAccommodation.accommodationPaid);
  setJobAccommodationArrangement(repeatedAccommodation.accommodationArrangement);
  setInputValue(
    "jobAccommodationAllowance",
    repeatedAccommodation.accommodationAllowancePerNight || "",
  );
  const hasProjectOvertimePolicy = Object.prototype.hasOwnProperty.call(
    job,
    "overtimeAvailable",
  );
  setCheckboxValue(
    "jobOvertimeAvailable",
    hasProjectOvertimePolicy
      ? !!job.overtimeAvailable
      : !!sourceFirstReq.overtimeAvailable,
  );
  const overtimeRates = job.overtimeRates || sourceFirstReq.overtimeRates || {};
  setSelectValue(document.getElementById("jobAfterHoursRateType"), overtimeRates.afterStandardHours || "standard");
  setSelectValue(document.getElementById("jobSaturdayRateType"), overtimeRates.saturday || "standard");
  setSelectValue(document.getElementById("jobSundayRateType"), overtimeRates.sunday || "standard");
  updateAssignmentTypeForm();
  updateAccommodationForm();
  updateOvertimeForm();
  syncTradeReqBuilderState();
  requestAnimationFrame(() => {
    updateJobPhotoPreviews();
    updatePinCoords();
    syncJobSiteDisclosureState();
  });
  document.querySelector("#formJob .jw-form")?.insertAdjacentHTML("afterbegin", repeatProjectNoticeHTML(job));
  document.querySelector("[data-repeat-clear]")?.addEventListener("click", () => {
    clearRepeatProjectTemplate();
    jobForm.reset();
    jobLocationPicker?.clear({ clearInput: true, emit: false });
    resetJobTradeRequirements();
    resetJobPhotos();
    jobWizardShiftDefaultsInitialized = false;
    initializeNewRequestShiftDefaults();
    currentJobPin = { lat: null, lng: null };
    jobArrivalPointSource = "";
    jobArrivalPointAddress = "";
    syncPickerMarkerToCurrentPin();
    updateAssignmentTypeForm();
    updateAccommodationForm();
    updateOvertimeForm();
    prepareJobSiteDisclosures();
  });
}

function repeatProject(jobId) {
  const job = findJob(jobId);
  if (!job) return;
  openLabourRequestPage({ focus: false });
  applyRepeatProjectToForm(job);
  showToast("Project details copied — add new dates before submitting");
}

function closeLabourRequestWorkflow() {
  const formWrap = document.getElementById("formJob");
  const returnPoint = document.getElementById("jobFormReturnPoint");
  const modal = document.getElementById("labourRequestModal");
  if (!modal || (modal.classList.contains("hidden") && !(formWrap && modal.contains(formWrap)))) return;
  if (formWrap && returnPoint?.parentElement) {
    formWrap.classList.add("hidden");
    returnPoint.parentElement.insertBefore(formWrap, returnPoint.nextSibling);
  }
  hideWithMotion(modal, () => document.body.classList.remove("modal-open"));
}

function bindLabourRequestWorkflow(scope = document) {
  scope.querySelectorAll("[data-company-request-labour]").forEach((btn) => {
    btn.addEventListener("click", openLabourRequestWorkflow);
  });
}

document.querySelectorAll("[data-labour-request-close]").forEach((btn) => {
  btn.addEventListener("click", closeLabourRequestWorkflow);
});

document.addEventListener("click", (event) => {
  if (!event.target.closest("[data-labour-request-close]")) return;
  closeLabourRequestWorkflow();
});

document.addEventListener("keydown", (event) => {
  const modal = document.getElementById("labourRequestModal");
  if (event.key === "Escape" && modal && !modal.classList.contains("hidden")) {
    closeLabourRequestWorkflow();
  }
});

// ─── Request Labour Wizard shell (Phase A) ────────────────
// Wizard mode is explicit UI state: it is entered only while #formJob is
// mounted in the company Request Labour page and exited whenever the form
// moves to the legacy modal, so the modal keeps its native validation and
// submission behaviour untouched. The COMPANY wizard cannot submit in
// Phase A — see the capture-phase submit guard below.
const JOB_WIZARD_STEPS = [
  "Project",
  "Labour",
  "Schedule",
  "Site & Attendance",
  "Pre-start",
  "Review",
];
let jobWizardActive = false;
let jobWizardStep = 1;
let jobWizardCompleted = new Set();
let jobWizardEnteredFromReview = false;
let jobWizardSubmissionApproved = false;
let jobWizardSubmissionInProgress = false;
let jobLabourMoreOptionsOpen = false;
let jobRequestedWorkerIds = [];
let specificWorkerPickerDraftIds = new Set();
let jobSpecificWorkerPickerSource = "previous";
let jobSpecificWorkerPickerQuery = "";
let jobSpecificWorkerPickerTrigger = null;
let jobArrivalDetailsOpen = false;
let jobEntrancePinOpen = false;
let jobArrivalPointSource = "";
let jobArrivalPointAddress = "";
let jobSitePhotosOpen = false;
let jobAttendanceManagerOpen = false;
let jobWizardShiftDefaultsInitialized = false;

function initializeNewRequestShiftDefaults() {
  if (jobWizardShiftDefaultsInitialized) return;
  const shiftStart = document.getElementById("jobShiftStart");
  const shiftFinish = document.getElementById("jobShiftFinish");
  if (!shiftStart || !shiftFinish) return;
  if (!shiftStart.value) shiftStart.value = "07:00";
  if (!shiftFinish.value) shiftFinish.value = "17:00";
  jobWizardShiftDefaultsInitialized = true;
}

function labourRequirementHasAdvancedOptions(requirement = {}) {
  return !!accommodationArrangementFor(requirement);
}

function syncJobLabourDisclosureState() {
  const panel = document.getElementById("jobLabourMoreOptionsPanel");
  panel?.classList.remove("hidden");
}

function syncJobPreferredWorkersDisclosureState() {
  renderJobPreferredWorkerChoices(getSessionUser());
}

function formFieldHasValue(id) {
  return !!String(document.getElementById(id)?.value || "").trim();
}

function jobArrivalDetailsHaveValues() {
  return ["jobArrivalInstructions", "jobParking", "jobPpe", "jobGateAccess"].some(
    formFieldHasValue,
  );
}

function jobAttendanceManagerHasValues() {
  return [
    "attendanceManagerName",
    "attendanceManagerEmail",
    "attendanceManagerPhone",
  ].some(formFieldHasValue);
}

function currentJobHasEntrancePin() {
  return !!(
    currentJobPin?.lat != null &&
    currentJobPin?.lng != null &&
    Number.isFinite(Number(currentJobPin.lat)) &&
    Number.isFinite(Number(currentJobPin.lng))
  );
}

function normalizedJobSiteAddress(value = document.getElementById("jobSiteAddress")?.value) {
  return String(value || "")
    .trim()
    .replace(/\s+/g, " ")
    .toLocaleLowerCase("en-GB");
}

function currentJobPhotoCount() {
  return Object.values(currentJobPhotos || {}).filter(Boolean).length;
}

function syncJobSiteDisclosureState() {
  const wizard = jobWizardActive;
  const disclosureStates = [
    ["jobArrivalDetailsPanel", "jobArrivalDetailsToggle", jobArrivalDetailsOpen],
    ["jobSitePhotosPanel", "jobSitePhotosToggle", jobSitePhotosOpen],
    ["jobAttendanceManagerPanel", "jobAttendanceManagerToggle", jobAttendanceManagerOpen],
  ];
  disclosureStates.forEach(([panelId, toggleId, open]) => {
    const expanded = !wizard || open;
    document.getElementById(panelId)?.classList.toggle("hidden", !expanded);
    document.getElementById(toggleId)?.setAttribute("aria-expanded", String(expanded));
  });
  document.getElementById("jobEntrancePinPanel")?.classList.remove("hidden");

  const arrivalToggle = document.getElementById("jobArrivalDetailsToggle");
  const arrivalSummary = document.getElementById("jobArrivalDetailsSummary");
  const hasArrivalDetails = jobArrivalDetailsHaveValues();
  if (arrivalSummary) {
    arrivalSummary.textContent = hasArrivalDetails
      ? "Added"
      : "Add instructions, parking, PPE or worker notes.";
  }
  if (arrivalToggle) {
    arrivalToggle.textContent = jobArrivalDetailsOpen
      ? "Done"
      : hasArrivalDetails
        ? "Edit"
        : "Add details";
  }

  const hasPin = currentJobHasEntrancePin();
  const pinSummary = document.getElementById("jobEntrancePinSummary");
  const pinToggle = document.getElementById("jobEntrancePinToggle");
  const pinHelper = document.getElementById("jobArrivalPointHelper");
  document
    .getElementById("jobPickerMap")
    ?.classList.toggle("is-adjusting", wizard && jobEntrancePinOpen);
  if (pinSummary) {
    pinSummary.textContent = hasPin
      ? jobArrivalPointSource === "manual"
        ? "Adjusted manually"
        : jobArrivalPointSource === "address"
          ? "Set from site address"
          : "Arrival point set"
      : "Not set";
    pinSummary.classList.toggle("is-set", hasPin);
    pinSummary.classList.toggle("is-unset", !hasPin);
  }
  if (pinToggle) {
    pinToggle.textContent = jobEntrancePinOpen ? "Done" : "Adjust arrival point";
    pinToggle.classList.toggle("hidden", wizard && !hasPin);
    pinToggle.setAttribute("aria-expanded", String(wizard && jobEntrancePinOpen));
  }
  pinHelper?.classList.toggle("hidden", !wizard || !jobEntrancePinOpen);

  const photoCount = currentJobPhotoCount();
  const photoSummary = document.getElementById("jobSitePhotosSummary");
  const photoToggle = document.getElementById("jobSitePhotosToggle");
  if (photoSummary) {
    photoSummary.textContent = photoCount
      ? `${photoCount} photo${photoCount === 1 ? "" : "s"} added`
      : "No photos added";
  }
  if (photoToggle) {
    photoToggle.textContent = jobSitePhotosOpen
      ? "Done"
      : photoCount
        ? "Manage photos"
        : "Add photos";
  }

  const managerToggle = document.getElementById("jobAttendanceManagerToggle");
  const hasManager = jobAttendanceManagerHasValues();
  const managerSummary = document.getElementById("jobAttendanceManagerSummary");
  if (managerSummary) {
    managerSummary.textContent = hasManager
      ? "Attendance manager assigned"
      : "Company-managed by default";
  }
  if (managerToggle) {
    managerToggle.textContent = jobAttendanceManagerOpen
      ? "Done"
      : hasManager
        ? "Edit manager"
        : "Assign attendance manager";
  }
}

function prepareJobSiteDisclosures() {
  jobArrivalDetailsOpen = false;
  jobEntrancePinOpen = false;
  jobSitePhotosOpen = false;
  jobAttendanceManagerOpen = false;
  syncJobSiteDisclosureState();
}

function setJobEntrancePinDisclosure(open) {
  jobEntrancePinOpen = !!open;
  syncJobSiteDisclosureState();
  syncPickerMarkerToCurrentPin();
  if (jobEntrancePinOpen || !jobWizardActive) {
    requestAnimationFrame(() => initPickerMap());
  }
}

const DRAFT_PRE_START_SETUP_STATUSES = new Set([
  "configured",
  "pending",
  "none",
]);
let draftPreStartSetupStatus = "";
let draftPreStartRequirements = [];

function resetDraftPreStartConfiguration({ renderStep = false } = {}) {
  draftPreStartSetupStatus = "";
  draftPreStartRequirements = [];
  if (renderStep) renderDraftPreStartStep();
}

function normalizeDraftPreStartRequirement(requirement, existing = null) {
  return normalizePreStartDocument({
    ...requirement,
    documentId:
      requirement?.documentId || existing?.documentId || createId(),
    createdAt:
      existing?.createdAt || requirement?.createdAt || new Date().toISOString(),
    uploadedAt:
      existing?.uploadedAt || requirement?.uploadedAt || new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    archivedAt: "",
  });
}

function upsertDraftPreStartRequirement(requirement) {
  const requirementId = String(requirement?.documentId || "");
  const existingIndex = requirementId
    ? draftPreStartRequirements.findIndex(
        (item) => item.documentId === requirementId,
      )
    : -1;
  const existing =
    existingIndex >= 0 ? draftPreStartRequirements[existingIndex] : null;
  const normalized = normalizeDraftPreStartRequirement(requirement, existing);
  if (!normalized) {
    return { ok: false, reason: "Enter a requirement title." };
  }
  if (existingIndex >= 0) draftPreStartRequirements[existingIndex] = normalized;
  else draftPreStartRequirements.push(normalized);
  draftPreStartSetupStatus = "configured";
  setDraftPreStartValidation();
  return { ok: true, updated: existingIndex >= 0, requirement: normalized };
}

function removeDraftPreStartRequirement(requirementId) {
  const previousLength = draftPreStartRequirements.length;
  draftPreStartRequirements = draftPreStartRequirements.filter(
    (requirement) => requirement.documentId !== requirementId,
  );
  setDraftPreStartValidation();
  return previousLength === draftPreStartRequirements.length
    ? { ok: false, reason: "Draft requirement not found." }
    : { ok: true };
}

function getDraftPreStartSubmissionPayload() {
  return {
    setupStatus: DRAFT_PRE_START_SETUP_STATUSES.has(
      draftPreStartSetupStatus,
    )
      ? draftPreStartSetupStatus
      : "",
    requirements: draftPreStartRequirements
      .map((requirement) => normalizeDraftPreStartRequirement(requirement, requirement))
      .filter(Boolean)
      .map((requirement) => structuredClone(requirement)),
  };
}

function finalizeDraftPreStartConfiguration(finalLabourRequirements) {
  const payload = getDraftPreStartSubmissionPayload();
  if (!DRAFT_PRE_START_SETUP_STATUSES.has(payload.setupStatus)) {
    throw new Error("Choose how pre-start requirements will be handled.");
  }
  if (payload.setupStatus !== "configured") {
    return { setupStatus: payload.setupStatus, requirements: [] };
  }

  const finalRequirements = Array.isArray(finalLabourRequirements)
    ? finalLabourRequirements
    : [];
  const finalById = new Map(
    finalRequirements.map((requirement) => [requirement.id, requirement]),
  );
  const draftToFinalId = new Map(
    pendingTradeRequirements.map((draftRequirement) => {
      const persisted =
        finalById.get(draftRequirement.id) ||
        finalRequirements.find((requirement) =>
          sameTradeRequirement(requirement, draftRequirement),
        );
      return [draftRequirement.id, persisted?.id || ""];
    }),
  );

  const requirements = payload.requirements.map((requirement) => {
    const audience = normalizeProjectRequirementAudience(requirement.audience);
    if (audience.type !== "labour_requirement") return requirement;
    const finalRequirementId = draftToFinalId.get(
      audience.labourRequirementId,
    );
    if (!finalRequirementId) {
      throw new Error(
        `Review the labour assignment for ${requirement.documentName}.`,
      );
    }
    return normalizeDraftPreStartRequirement(
      {
        ...requirement,
        audience: {
          type: "labour_requirement",
          labourRequirementId: finalRequirementId,
        },
      },
      requirement,
    );
  });

  if (requirements.length !== payload.requirements.length) {
    throw new Error("Review the pre-start requirements before finding labour.");
  }
  return { setupStatus: payload.setupStatus, requirements };
}

function draftPreStartRequirementAssignmentIssue(requirement) {
  if (requirement?.audience?.type !== "labour_requirement") return false;
  return !pendingTradeRequirements.some(
    (labourRequirement) =>
      labourRequirement.id === requirement.audience.labourRequirementId,
  );
}

function draftPreStartRequirementReadiness(requirement) {
  if (draftPreStartRequirementAssignmentIssue(requirement)) {
    return { label: "Needs assignment review", tone: "is-review" };
  }
  if (requirement.contentToFollow) {
    return { label: "Content to follow", tone: "is-pending" };
  }
  return { label: "Ready", tone: "is-ready" };
}

function draftPreStartRequirementRowHTML(requirement) {
  const readiness = draftPreStartRequirementReadiness(requirement);
  const resourceSummary = projectRequirementResourceSummary(
    requirement.resources,
  );
  return `<article class="jw-prestart-requirement-row">
    <div class="jw-prestart-requirement-main">
      <strong>${escapeHtml(requirement.documentName)}</strong>
      <span>${escapeHtml(projectRequirementTypeLabel(requirement.requirementType))} · ${escapeHtml(requirement.requirementLevel === "optional" ? "Optional" : "Required")} · ${escapeHtml(projectRequirementTimingLabel(requirement.timing))} · ${escapeHtml(projectRequirementConfiguredActionLabel(requirement))}</span>
    </div>
    <div class="jw-prestart-requirement-meta">
      <span>${escapeHtml(projectRequirementAudienceLabelFromRequirements(pendingTradeRequirements, requirement))}</span>
      <span>${escapeHtml(resourceSummary)}</span>
    </div>
    <span class="jw-prestart-readiness ${readiness.tone}">${escapeHtml(readiness.label)}</span>
    <div class="jw-prestart-requirement-actions">
      <button type="button" data-draft-prestart-edit="${escapeHtml(requirement.documentId)}">Edit</button>
      <button type="button" data-draft-prestart-remove="${escapeHtml(requirement.documentId)}">Remove</button>
    </div>
  </article>`;
}

function draftPreStartRequirementListHTML() {
  return PROJECT_REQUIREMENT_TIMINGS.map((timing) => {
    const requirements = draftPreStartRequirements.filter(
      (requirement) => requirement.timing === timing.value,
    );
    if (!requirements.length) return "";
    const label =
      timing.value === "reference_anytime"
        ? "Optional / reference"
        : timing.label;
    return `<section class="jw-prestart-requirement-group" aria-labelledby="draft-prestart-${timing.value}">
      <h4 id="draft-prestart-${timing.value}">${escapeHtml(label)}</h4>
      <div>${requirements.map(draftPreStartRequirementRowHTML).join("")}</div>
    </section>`;
  }).join("");
}

function draftPreStartConfiguredHTML() {
  return `<section class="jw-prestart-configured" aria-labelledby="jobPreStartConfiguredTitle">
    <div class="jw-prestart-state-head">
      <div><h4 id="jobPreStartConfiguredTitle">Project requirements</h4><p>Add each action workers need to complete for this project.</p></div>
      <button class="secondary-btn" type="button" data-draft-prestart-add>+ Add requirement</button>
    </div>
    ${draftPreStartRequirements.length
      ? `<div class="jw-prestart-requirement-list">${draftPreStartRequirementListHTML()}</div>`
      : `<div class="jw-prestart-empty"><strong>No requirements added.</strong><span>Add the first pre-start requirement to continue.</span></div>`}
  </section>`;
}

function draftPreStartStateHTML() {
  if (draftPreStartSetupStatus === "configured") {
    return draftPreStartConfiguredHTML();
  }
  if (draftPreStartSetupStatus === "pending") {
    return `<div class="jw-prestart-message is-pending"><strong>Pre-start setup pending</strong><span>You can finish the requirements from the project after it is created.</span></div>`;
  }
  if (draftPreStartSetupStatus === "none") {
    return `<div class="jw-prestart-message"><strong>No pre-start requirements</strong><span>No pre-start requirements will be added to this project.</span></div>`;
  }
  return "";
}

function setDraftPreStartValidation(message = "") {
  const validation = document.getElementById("jobPreStartValidation");
  if (!validation) return;
  validation.textContent = message;
  validation.classList.toggle("hidden", !message);
}

function renderDraftPreStartStep() {
  document
    .querySelectorAll('input[name="jobPreStartSetupStatus"]')
    .forEach((input) => {
      input.checked = input.value === draftPreStartSetupStatus;
    });
  const body = document.getElementById("jobPreStartStateBody");
  if (body) body.innerHTML = draftPreStartStateHTML();
}

function validateDraftPreStartStep({ report = true } = {}) {
  if (!DRAFT_PRE_START_SETUP_STATUSES.has(draftPreStartSetupStatus)) {
    if (report) {
      setDraftPreStartValidation(
        "Choose how pre-start requirements will be handled for this project.",
      );
      document
        .querySelector('input[name="jobPreStartSetupStatus"]')
        ?.focus();
    }
    return false;
  }
  if (
    draftPreStartSetupStatus === "configured" &&
    !draftPreStartRequirements.length
  ) {
    if (report) {
      setDraftPreStartValidation(
        "Add at least one pre-start requirement to continue, or choose a different setup option.",
      );
      document.querySelector("[data-draft-prestart-add]")?.focus();
    }
    return false;
  }
  const assignmentIssue = draftPreStartRequirements.find(
    draftPreStartRequirementAssignmentIssue,
  );
  if (draftPreStartSetupStatus === "configured" && assignmentIssue) {
    if (report) {
      setDraftPreStartValidation(
        `Review the assignment for ${assignmentIssue.documentName} before continuing.`,
      );
      document
        .querySelector(
          `[data-draft-prestart-edit="${CSS.escape(assignmentIssue.documentId)}"]`,
        )
        ?.focus();
    }
    return false;
  }
  const invalidRequirement = draftPreStartRequirements.find((requirement) =>
    projectRequirementDraftValidationIssue({
      mode: "draft",
      draft: requirement,
    }),
  );
  if (draftPreStartSetupStatus === "configured" && invalidRequirement) {
    if (report) {
      setDraftPreStartValidation(
        `Review ${invalidRequirement.documentName} before continuing.`,
      );
      document
        .querySelector(
          `[data-draft-prestart-edit="${CSS.escape(invalidRequirement.documentId)}"]`,
        )
        ?.focus();
    }
    return false;
  }
  if (report) setDraftPreStartValidation();
  return true;
}

function closeDraftPreStartConfirmDialog() {
  hideWithMotion(
    document.getElementById("draftPreStartConfirmModal"),
    null,
    { remove: true },
  );
}

function openDraftPreStartConfirmDialog({
  title,
  description,
  confirmLabel,
  onConfirm,
  trigger = null,
}) {
  document.getElementById("draftPreStartConfirmModal")?.remove();
  const modal = document.createElement("div");
  modal.id = "draftPreStartConfirmModal";
  modal.className = "modal-overlay";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-labelledby", "draftPreStartConfirmTitle");
  modal.innerHTML = `<div class="dispute-sheet jw-requirement-guard-sheet">
    <div class="dispute-sheet-header"><div><h3 class="dispute-sheet-title" id="draftPreStartConfirmTitle">${escapeHtml(title)}</h3></div><button class="modal-close-btn" type="button" aria-label="Close" data-draft-prestart-confirm-cancel>×</button></div>
    <div class="dispute-sheet-body"><p class="jw-requirement-guard-copy">${escapeHtml(description)}</p><div class="jw-requirement-guard-actions"><button class="secondary-btn" type="button" data-draft-prestart-confirm-cancel>Keep requirements</button><button class="primary-btn" type="button" data-draft-prestart-confirm>${escapeHtml(confirmLabel)}</button></div></div>
  </div>`;
  document.body.appendChild(modal);
  const close = () => {
    closeDraftPreStartConfirmDialog();
    if (trigger instanceof HTMLElement) trigger.focus();
  };
  modal
    .querySelectorAll("[data-draft-prestart-confirm-cancel]")
    .forEach((button) => button.addEventListener("click", close));
  modal.querySelector("[data-draft-prestart-confirm]")?.addEventListener("click", () => {
    closeDraftPreStartConfirmDialog();
    onConfirm();
  });
  modal.addEventListener("click", (event) => {
    if (event.target === modal) close();
  });
  modal.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      close();
      return;
    }
    trapProjectRequirementModalFocus(modal, event);
  });
  modal.querySelector("[data-draft-prestart-confirm-cancel]")?.focus();
}

function requestDraftPreStartSetupStatus(status, trigger) {
  if (!DRAFT_PRE_START_SETUP_STATUSES.has(status)) return;
  if (
    draftPreStartSetupStatus === "configured" &&
    status !== "configured" &&
    draftPreStartRequirements.length
  ) {
    renderDraftPreStartStep();
    openDraftPreStartConfirmDialog({
      title: "Discard configured requirements?",
      description:
        "Switching setup option will remove only the pre-start requirements configured in this request.",
      confirmLabel: "Discard requirements and switch",
      trigger,
      onConfirm: () => {
        draftPreStartRequirements = [];
        draftPreStartSetupStatus = status;
        setDraftPreStartValidation();
        renderDraftPreStartStep();
      },
    });
    return;
  }
  draftPreStartSetupStatus = status;
  setDraftPreStartValidation();
  renderDraftPreStartStep();
}

document
  .querySelectorAll('input[name="jobPreStartSetupStatus"]')
  .forEach((input) =>
    input.addEventListener("change", (event) =>
      requestDraftPreStartSetupStatus(
        event.currentTarget.value,
        event.currentTarget,
      ),
    ),
  );

document.addEventListener("click", (event) => {
  const add = event.target.closest("[data-draft-prestart-add]");
  if (add) {
    openDraftPreStartRequirementModal("", add);
    return;
  }
  const edit = event.target.closest("[data-draft-prestart-edit]");
  if (edit) {
    openDraftPreStartRequirementModal(edit.dataset.draftPrestartEdit, edit);
    return;
  }
  const remove = event.target.closest("[data-draft-prestart-remove]");
  if (!remove) return;
  const requirement = draftPreStartRequirements.find(
    (item) => item.documentId === remove.dataset.draftPrestartRemove,
  );
  if (!requirement) return;
  openDraftPreStartConfirmDialog({
    title: "Remove pre-start requirement?",
    description: `${requirement.documentName} will be removed from this request.`,
    confirmLabel: "Remove requirement",
    trigger: remove,
    onConfirm: () => {
      removeDraftPreStartRequirement(requirement.documentId);
      renderDraftPreStartStep();
      showToast("Pre-start requirement removed");
    },
  });
});

function mountJobPricingBreakdown(mountId) {
  const panel = document.getElementById("jobPricingBreakdown");
  const mount = document.getElementById(mountId);
  if (panel && mount && panel.parentElement !== mount) mount.appendChild(panel);
}

function enterJobWizardMode({ reset = false } = {}) {
  const formWrap = document.getElementById("formJob");
  if (!formWrap || !jobForm) return;
  const wasActive = jobWizardActive;
  jobWizardActive = true;
  formWrap.classList.add("jw-wizard-mode");
  const projectStart = document.getElementById("jobStart");
  if (projectStart) {
    const startDate = splitProjectStartValue(projectStart.value).date;
    projectStart.type = "date";
    projectStart.value = startDate;
  }
  mountJobPricingBreakdown("jobPricingBreakdownWizardMount");
  // Context-specific novalidate: only while the form operates as the
  // company wizard. Removed again in exitJobWizardMode().
  jobForm.setAttribute("novalidate", "");
  if (reset || !wasActive) {
    jobWizardStep = 1;
    jobWizardCompleted = new Set();
    jobWizardEnteredFromReview = false;
    jobWizardSubmissionApproved = false;
    jobWizardSubmissionInProgress = false;
    jobLabourMoreOptionsOpen = false;
    jobArrivalDetailsOpen = false;
    jobEntrancePinOpen = false;
    jobSitePhotosOpen = false;
    jobAttendanceManagerOpen = false;
  }
  initializeNewRequestShiftDefaults();
  syncJobLabourDisclosureState();
  syncJobPreferredWorkersDisclosureState();
  syncJobSiteDisclosureState();
  goToJobWizardStep(jobWizardStep, { scroll: false });
}

function exitJobWizardMode() {
  jobWizardActive = false;
  document.getElementById("formJob")?.classList.remove("jw-wizard-mode");
  const projectStart = document.getElementById("jobStart");
  if (projectStart) {
    const startDate = splitProjectStartValue(projectStart.value).date;
    const startTime = document.getElementById("jobShiftStart")?.value || "";
    projectStart.type = "datetime-local";
    projectStart.value = composeProjectStartValue(startDate, startTime);
  }
  mountJobPricingBreakdown("jobPricingBreakdownLegacyMount");
  jobForm?.removeAttribute("novalidate");
  syncJobLabourDisclosureState();
  syncJobPreferredWorkersDisclosureState();
  syncJobSiteDisclosureState();
}

function jobWizardStepNavigable(step) {
  if (step < 1 || step > JOB_WIZARD_STEPS.length) return false;
  if (step === jobWizardStep) return true;
  if (jobWizardCompleted.has(step)) return true;
  // The first not-yet-completed step is reachable; later ones are not.
  for (let s = 1; s < step; s++) {
    if (!jobWizardCompleted.has(s)) return false;
  }
  return true;
}

function jobWizardReviewRowsHTML(rows) {
  const visible = rows.filter(([, value]) => String(value ?? "").trim());
  if (!visible.length) return "";
  return `<dl class="jw-review-rows">${visible
    .map(
      ([label, value]) =>
        `<div><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(value)}</dd></div>`,
    )
    .join("")}</dl>`;
}

function jobWizardReviewSectionHTML({ key, title, step, content }) {
  const headingId = `jobReview${key.replace(/[^a-z0-9]+/gi, "")}Title`;
  return `<section class="jw-review-section" aria-labelledby="${headingId}">
    <header class="jw-review-section-head">
      <div><p>${escapeHtml(key)}</p><h4 id="${headingId}">${escapeHtml(title)}</h4></div>
      <button type="button" class="jw-inline-link" data-job-review-edit="${step}">Edit &rarr;</button>
    </header>
    ${content}
  </section>`;
}

function jobWizardProjectReviewHTML() {
  const assignmentType = document.getElementById("jobAssignmentType")?.value;
  return jobWizardReviewSectionHTML({
    key: "PROJECT",
    title: "Project",
    step: 1,
    content: jobWizardReviewRowsHTML([
      ["Project name", document.getElementById("projectName")?.value.trim()],
      ["Job number", document.getElementById("jobNumber")?.value.trim()],
      [
        "Assignment type",
        assignmentType
          ? assignmentTypeLabel({ assignmentType })
          : "",
      ],
      ["Location", document.getElementById("jobLocation")?.value.trim()],
    ]),
  });
}

function overtimeRateTypeLabel(value) {
  return {
    standard: "Standard rate",
    time_and_third: "Time and a third",
    time_and_half: "Time and a half",
    double_time: "Double time",
    custom: "Custom",
  }[value] || "Standard rate";
}

function jobWizardLabourRequirementReviewHTML(requirement) {
  const quantity = Math.max(1, Number(requirement.quantity) || 1);
  const identity = [requirement.specialism, `${quantity} worker${quantity === 1 ? "" : "s"}`]
    .filter(Boolean)
    .join(" · ");
  const detail = [requirement.grade, requirement.workActivity]
    .filter(Boolean)
    .join(" · ");
  const conditions = [];
  if (requirement.accommodationPaid) {
    conditions.push(accommodationSummaryFor(requirement));
  }
  conditions.push(
    requirement.workerReceivesFullAdvertisedRate !== false
      ? "Worker receives full advertised rate"
      : "Service fee included within advertised rate",
  );
  const credentialSummary = credentialLabelsForRequirement(requirement).join(" · ");
  return `<article class="jw-review-labour-row">
    <div class="jw-review-labour-identity">
      <strong>${escapeHtml(requirement.trade || "Labour requirement")}</strong>
      ${identity ? `<span>${escapeHtml(identity)}</span>` : ""}
      ${detail ? `<span>${escapeHtml(detail)}</span>` : ""}
      ${credentialSummary ? `<span>${escapeHtml(credentialSummary)}</span>` : ""}
    </div>
    <div class="jw-review-labour-terms">
      ${requirement.budgetMax ? `<strong>${formatMoney(requirement.budgetMax)}/day</strong>` : ""}
      ${conditions.map((condition) => `<span>${escapeHtml(condition)}</span>`).join("")}
    </div>
  </article>`;
}

function jobWizardPreferredWorkersReviewHTML() {
  const ids = preferredWorkerIdsFromJobForm();
  if (!ids.length) return "";
  const companyId = getSessionUser()?.id || "";
  const previousWorkers = companyPreviousWorkerHistory(companyId);
  return `<div class="jw-review-specific-workers" aria-label="Specific workers requested for this labour request">
    <span class="jw-review-specific-workers-label">Specific workers</span>
    ${ids
      .map((workerId) => {
        const worker = findWorker(workerId);
        if (!worker) return "";
        const role = [worker.trade, worker.specialism || worker.grade]
          .filter(Boolean)
          .join(" · ") || "Trade not set";
        const statuses = [
          isPreferredWorker(companyId, worker.id) ? "★ Preferred" : "",
          previousWorkers.has(worker.id) ? "Previous worker" : "",
        ].filter(Boolean);
        return `<article class="jw-review-specific-worker">
          ${specificWorkerAvatarHTML(worker, "jw-review-worker-avatar")}
          <div class="jw-review-specific-worker-copy">
            <strong>${escapeHtml(worker.name || "Worker")}</strong>
            <span>${escapeHtml(role)}</span>
          </div>
          ${statuses.length ? `<div class="jw-review-specific-worker-status">${statuses.map((status) => `<span>${escapeHtml(status)}</span>`).join("")}</div>` : ""}
        </article>`;
      })
      .join("")}
  </div>`;
}

function jobWizardLabourReviewHTML() {
  const totalWorkers = pendingTradeRequirements.reduce(
    (sum, requirement) => sum + Math.max(1, Number(requirement.quantity) || 1),
    0,
  );
  const content = pendingTradeRequirements.length
    ? `<div class="jw-review-labour-list">${pendingTradeRequirements
        .map(jobWizardLabourRequirementReviewHTML)
        .join("")}</div>`
    : `<p class="jw-review-empty">No saved labour requirements.</p>`;
  return jobWizardReviewSectionHTML({
    key: "LABOUR",
    title: "Labour",
    step: 2,
    content: `${content}
      <div class="jw-review-totals"><span>Total workers <strong>${totalWorkers}</strong></span><span>Labour requirements <strong>${pendingTradeRequirements.length}</strong></span></div>
      ${jobWizardPreferredWorkersReviewHTML()}`,
  });
}

function jobWizardScheduleReviewHTML() {
  const start = document.getElementById("jobStart")?.value || "";
  const noFixedEndDate = !!document.getElementById("jobNoFixedEndDate")?.checked;
  const end = document.getElementById("jobEndDate")?.value || "";
  const shiftStart = document.getElementById("jobShiftStart")?.value || "";
  const shiftFinish = document.getElementById("jobShiftFinish")?.value || "";
  const workingDays = selectedJobWorkingDays()
    .map((day) => WORKING_DAY_LABELS[day]?.slice(0, 3) || "")
    .filter(Boolean)
    .join(" · ");
  const overtimeAvailable = !!document.getElementById("jobOvertimeAvailable")?.checked;
  const overtimeRates = {
    afterStandardHours:
      document.getElementById("jobAfterHoursRateType")?.value || "standard",
    saturday:
      document.getElementById("jobSaturdayRateType")?.value || "standard",
    sunday:
      document.getElementById("jobSundayRateType")?.value || "standard",
  };
  const rows = [
    ["Project start", start ? formatDateOnly(start) : ""],
    [
      "Estimated end",
      noFixedEndDate ? "No fixed end date" : end ? formatDateOnly(end) : "",
    ],
    [
      "Standard shift",
      [shiftStart, shiftFinish].filter(Boolean).join("–"),
    ],
    ["Working days", workingDays],
    ["Overtime", overtimeAvailable ? "Available" : "Not available"],
  ];
  if (overtimeAvailable) {
    rows.push(
      ["After-hours", overtimeRateTypeLabel(overtimeRates.afterStandardHours)],
      ["Saturday", overtimeRateTypeLabel(overtimeRates.saturday)],
      ["Sunday", overtimeRateTypeLabel(overtimeRates.sunday)],
    );
  }
  return jobWizardReviewSectionHTML({
    key: "SCHEDULE & PAY",
    title: "Schedule & pay",
    step: 3,
    content: jobWizardReviewRowsHTML(rows),
  });
}

function jobWizardSiteReviewHTML() {
  const contactName = document.getElementById("jobContactName")?.value.trim() || "";
  const contactPhone = document.getElementById("jobContactPhone")?.value.trim() || "";
  const managerName = document.getElementById("attendanceManagerName")?.value.trim() || "";
  const managerEmail = document.getElementById("attendanceManagerEmail")?.value.trim() || "";
  const managerPhone = document.getElementById("attendanceManagerPhone")?.value.trim() || "";
  const hasPin =
    currentJobPin?.lat != null &&
    currentJobPin?.lng != null &&
    Number.isFinite(Number(currentJobPin.lat)) &&
    Number.isFinite(Number(currentJobPin.lng));
  const photoCount = Object.values(currentJobPhotos || {}).filter(Boolean).length;
  const arrivalPoint = hasPin
    ? jobArrivalPointSource === "manual"
      ? "Adjusted manually"
      : jobArrivalPointSource === "address"
        ? "Set from site address"
        : "Set"
    : "Not set";
  const attendanceSetup = managerName
    ? [managerName, managerEmail, managerPhone].filter(Boolean).join(" · ")
    : "Company-managed";
  return jobWizardReviewSectionHTML({
    key: "SITE & ATTENDANCE",
    title: "Site & attendance",
    step: 4,
    content: jobWizardReviewRowsHTML([
      ["Site address", document.getElementById("jobSiteAddress")?.value.trim()],
      ["Site contact name", contactName],
      ["Site contact phone", contactPhone],
      [
        "Arrival instructions",
        document.getElementById("jobArrivalInstructions")?.value.trim(),
      ],
      ["Parking", document.getElementById("jobParking")?.value.trim()],
      ["PPE", document.getElementById("jobPpe")?.value.trim()],
      [
        "Additional notes",
        document.getElementById("jobGateAccess")?.value.trim(),
      ],
      ["Arrival point", arrivalPoint],
      [
        "Site photos",
        photoCount
          ? `${photoCount} photo${photoCount === 1 ? "" : "s"} added`
          : "",
      ],
      ["Attendance setup", attendanceSetup],
    ]),
  });
}

function jobWizardPreStartReviewHTML() {
  let content = "";
  if (draftPreStartSetupStatus === "configured") {
    const ready = draftPreStartRequirements.filter(
      (requirement) =>
        !requirement.contentToFollow &&
        !draftPreStartRequirementAssignmentIssue(requirement),
    ).length;
    const contentToFollow = draftPreStartRequirements.filter(
      (requirement) => requirement.contentToFollow,
    ).length;
    const needsAssignmentReview = draftPreStartRequirements.filter(
      draftPreStartRequirementAssignmentIssue,
    ).length;
    const groups = PROJECT_REQUIREMENT_TIMINGS.map((timing) => {
      const requirements = draftPreStartRequirements.filter(
        (requirement) => requirement.timing === timing.value,
      );
      if (!requirements.length) return "";
      const label =
        timing.value === "reference_anytime"
          ? "Optional / reference"
          : timing.label;
      return `<div class="jw-review-prestart-group"><span>${escapeHtml(label)}</span>${requirements
        .map(
          (requirement) => {
            const readiness = draftPreStartRequirementReadiness(requirement);
            return `<div><strong>${escapeHtml(requirement.documentName)}</strong><small>${escapeHtml([
              projectRequirementTypeLabel(requirement.requirementType),
              requirement.requirementLevel === "optional" ? "Optional" : "Required",
              projectRequirementConfiguredActionLabel(requirement),
              projectRequirementAudienceLabelFromRequirements(
                pendingTradeRequirements,
                requirement,
              ),
              readiness.label,
            ].join(" · "))}</small></div>`;
          },
        )
        .join("")}</div>`;
    }).join("");
    content = `<div class="jw-review-readiness"><strong>${draftPreStartRequirements.length} requirement${draftPreStartRequirements.length === 1 ? "" : "s"}</strong><span>${ready} ready${contentToFollow ? ` · ${contentToFollow} content to follow` : ""}${needsAssignmentReview ? ` · ${needsAssignmentReview} need assignment review` : ""}</span></div>${groups}`;
  } else if (draftPreStartSetupStatus === "pending") {
    content = `<div class="jw-review-state is-warning"><strong>Pre-start setup pending</strong><span>Requirements can be completed from the project before workers start.</span></div>`;
  } else if (draftPreStartSetupStatus === "none") {
    content = `<div class="jw-review-state"><strong>No pre-start requirements</strong><span>This project has been explicitly marked as not requiring pre-start actions.</span></div>`;
  } else {
    content = `<div class="jw-review-state is-blocking"><strong>Pre-start setup not selected</strong><span>Choose how pre-start requirements will be handled before finding labour.</span></div>`;
  }
  return jobWizardReviewSectionHTML({
    key: "PRE-START",
    title: "Pre-start",
    step: 5,
    content,
  });
}

function jobWizardEstimatedCostReviewHTML() {
  const pricing = buildRequestLabourPricingModel(pendingTradeRequirements);
  const rows = [
    ["Total workers", String(pricing.totalWorkers)],
    ["Labour requirements", String(pricing.requirements.length)],
    ["Worker labour", formatMoney(pricing.totalWorkerLabour)],
    ["OnSite service fee", formatMoney(pricing.totalServiceFee)],
    ["VAT", formatMoney(pricing.totalVat)],
  ];
  return `<section class="jw-review-section jw-review-cost" aria-labelledby="jobReviewCostTitle">
    <header class="jw-review-section-head"><div><p>ESTIMATED COST</p><h4 id="jobReviewCostTitle">Estimated labour cost</h4></div></header>
    ${jobWizardReviewRowsHTML(rows)}
    <div class="jw-review-cost-total"><span>Estimated daily total</span><strong>${formatMoney(pricing.totalDailyCost)}</strong></div>
    ${pricing.totalAccommodation ? `<div class="jw-review-cost-accommodation"><span>Nightly accommodation allowances</span><strong>${formatMoney(pricing.totalAccommodation)}/night</strong></div>` : ""}
    <p class="jw-review-disclaimer">Final invoices are based on approved attendance and any applicable adjustments.</p>
  </section>`;
}

function jobWizardReviewWarningsHTML() {
  const warnings = [];
  if (draftPreStartSetupStatus === "pending") {
    warnings.push({
      step: 5,
      text: "Pre-start requirements will need to be configured from the project before workers are cleared to start.",
    });
  }
  const contentToFollow = draftPreStartRequirements.filter(
    (requirement) => requirement.contentToFollow,
  );
  if (draftPreStartSetupStatus === "configured" && contentToFollow.length) {
    warnings.push({
      step: 5,
      text: `${contentToFollow.length} pre-start requirement${contentToFollow.length === 1 ? " has" : "s have"} content to follow.`,
    });
  }
  if (!warnings.length) return "";
  return `<section class="jw-review-warnings" aria-labelledby="jobReviewWarningsTitle"><h4 id="jobReviewWarningsTitle">Items to review</h4>${warnings
    .map(
      (warning) => `<div><span>${escapeHtml(warning.text)}</span><button type="button" class="jw-inline-link" data-job-review-edit="${warning.step}">Edit &rarr;</button></div>`,
    )
    .join("")}</section>`;
}

function renderJobWizardReview() {
  const body = document.getElementById("jobWizardReviewBody");
  if (!body) return;
  body.innerHTML = [
    jobWizardProjectReviewHTML(),
    jobWizardLabourReviewHTML(),
    jobWizardScheduleReviewHTML(),
    jobWizardSiteReviewHTML(),
    jobWizardPreStartReviewHTML(),
    jobWizardEstimatedCostReviewHTML(),
    jobWizardReviewWarningsHTML(),
  ].join("");
}

function renderJobWizardChrome() {
  document.querySelectorAll("#formJob .jw-step").forEach((el) => {
    el.classList.toggle(
      "jw-step-active",
      Number(el.dataset.wizardStep) === jobWizardStep,
    );
  });
  document.querySelectorAll("[data-wizard-goto]").forEach((btn) => {
    const step = Number(btn.dataset.wizardGoto);
    const isCurrent = step === jobWizardStep;
    btn.classList.toggle("is-current", isCurrent);
    btn.classList.toggle("is-complete", jobWizardCompleted.has(step) && !isCurrent);
    btn.disabled = !jobWizardStepNavigable(step);
    if (isCurrent) btn.setAttribute("aria-current", "step");
    else btn.removeAttribute("aria-current");
  });
  const progress = document.getElementById("jobWizardProgress");
  if (progress) {
    const stepLabel = escapeHtml(JOB_WIZARD_STEPS[jobWizardStep - 1] || "");
    progress.innerHTML = `
      <span class="jw-wizard-progress-copy">
        <span class="jw-wizard-progress-count">Step ${jobWizardStep} of ${JOB_WIZARD_STEPS.length}</span>
        <strong class="jw-wizard-progress-label">${stepLabel}</strong>
      </span>
      <span class="jw-wizard-progress-track" aria-hidden="true"><span></span></span>
    `;
    progress.style.setProperty(
      "--jw-wizard-progress",
      `${(jobWizardStep / JOB_WIZARD_STEPS.length) * 100}%`,
    );
    progress.setAttribute(
      "aria-label",
      `Step ${jobWizardStep} of ${JOB_WIZARD_STEPS.length}: ${JOB_WIZARD_STEPS[jobWizardStep - 1] || ""}`,
    );
  }
  document
    .getElementById("jobWizardBack")
    ?.classList.toggle("hidden", jobWizardStep === 1);
  document
    .getElementById("jobWizardContinue")
    ?.classList.toggle("hidden", jobWizardStep === JOB_WIZARD_STEPS.length);
  const continueButton = document.getElementById("jobWizardContinue");
  if (continueButton) {
    continueButton.textContent =
      jobWizardEnteredFromReview && jobWizardStep < JOB_WIZARD_STEPS.length
        ? "Return to review"
        : "Continue";
    const labourStepBlocked =
      jobWizardStep === 2 && pendingTradeRequirements.length === 0;
    continueButton.disabled = labourStepBlocked;
    continueButton.setAttribute("aria-disabled", String(labourStepBlocked));
  }
  document
    .getElementById("jobWizardSubmit")
    ?.classList.toggle("hidden", jobWizardStep !== JOB_WIZARD_STEPS.length);
}

function goToJobWizardStep(step, { scroll = true } = {}) {
  const previousStep = jobWizardStep;
  jobWizardStep = Math.min(Math.max(step, 1), JOB_WIZARD_STEPS.length);
  renderJobWizardChrome();
  if (jobWizardStep === 2) {
    updateTradeRequirementEditorState();
    syncJobLabourDisclosureState();
    syncJobPreferredWorkersDisclosureState();
  }
  else {
    document.getElementById("formJob")?.classList.remove(
      "jw-requirement-editor-active",
      "jw-has-unsaved-requirement",
    );
  }
  if (jobWizardStep === 2) renderJobPricingBreakdown();
  if (jobWizardStep === 4) {
    if (previousStep !== 4) prepareJobSiteDisclosures();
    else syncJobSiteDisclosureState();
    requestAnimationFrame(() => initPickerMap());
  }
  if (jobWizardStep === 5) renderDraftPreStartStep();
  if (jobWizardStep === 6) {
    jobWizardEnteredFromReview = false;
    renderJobWizardReview();
  }
  if (scroll) scrollAppToTop();
}

// Per-step validation: native constraint checks on the visible step's
// controls only. Required-state decisions made elsewhere (e.g.
// syncTradeReqBuilderState, updateAssignmentTypeForm) are read, never
// overwritten. Phase C2 will layer full business validation on top.
function validateJobWizardStep(step, { report = true } = {}) {
  const container = document.querySelector(
    `#formJob .jw-step[data-wizard-step="${step}"]`,
  );
  if (!container) return true;
  const controls = container.querySelectorAll("input, select, textarea");
  for (const el of controls) {
    if (el.disabled || !el.willValidate) continue;
    if (el.closest(".hidden")) continue; // collapsed conditional sections
    if (!el.checkValidity()) {
      if (report) el.reportValidity();
      return false;
    }
  }
  return true;
}

function validateJobLocationSelection({ report = true } = {}) {
  const input = document.getElementById("jobLocation");
  if (!input) return false;
  if (!jobLocationPicker) {
    input.setCustomValidity(
      "UK town and city selection is unavailable. Refresh and try again.",
    );
    if (report) {
      input.reportValidity();
      input.focus();
    }
    return false;
  }
  return jobLocationPicker.validate({ report });
}

function validateSiteAttendanceWizardStep({ report = true } = {}) {
  const map = document.getElementById("jobPickerMap");
  const message = document.getElementById("jobEntrancePinMessage");
  const hasEntrancePin =
    currentJobPin?.lat != null &&
    currentJobPin?.lng != null &&
    Number.isFinite(Number(currentJobPin.lat)) &&
    Number.isFinite(Number(currentJobPin.lng));

  if (report) map?.setAttribute("aria-invalid", String(!hasEntrancePin));
  if (report && message) {
    message.textContent = hasEntrancePin
      ? ""
      : "Find the site on the map before continuing.";
    message.classList.toggle("hidden", hasEntrancePin);
  }
  if (report && !hasEntrancePin) {
    requestAnimationFrame(() => map?.focus({ preventScroll: true }));
  }
  return hasEntrancePin;
}

function validateRequestLabourWizardStep(step, { report = false } = {}) {
  if (step === 1 && !validateJobLocationSelection({ report })) return false;
  if (step === 2 && !validateLabourWizardStepNavigation({ report })) return false;
  if (!validateJobWizardStep(step, { report })) return false;
  if (step === 3 && !validateSchedulePayWizardStep({ report })) return false;
  if (step === 4 && !validateSiteAttendanceWizardStep({ report })) return false;
  if (step === 5 && !validateDraftPreStartStep({ report })) return false;
  return true;
}

function validateRequestLabourWizard() {
  for (let step = 1; step <= 5; step += 1) {
    if (!validateRequestLabourWizardStep(step, { report: false })) {
      return { valid: false, step };
    }
  }
  return { valid: true, step: 6 };
}

function routeToInvalidJobWizardStep(
  step,
  { preserveReviewReturn = false } = {},
) {
  jobWizardEnteredFromReview = preserveReviewReturn;
  goToJobWizardStep(step);
  requestAnimationFrame(() => {
    validateRequestLabourWizardStep(step, { report: true });
  });
}

function attemptReturnToJobWizardReview() {
  const validation = validateRequestLabourWizard();
  if (!validation.valid) {
    routeToInvalidJobWizardStep(validation.step, {
      preserveReviewReturn: true,
    });
    return;
  }
  for (let step = 1; step <= 5; step += 1) jobWizardCompleted.add(step);
  goToJobWizardStep(6);
}

function resetJobWizardSubmissionState() {
  jobWizardSubmissionApproved = false;
  jobWizardSubmissionInProgress = false;
  const submitButton = document.getElementById("jobWizardSubmit");
  if (submitButton) {
    submitButton.disabled = false;
    submitButton.textContent = "Find Labour";
  }
}

function submitRequestLabourWizard() {
  if (!jobWizardActive || jobWizardStep !== 6 || jobWizardSubmissionInProgress) {
    return;
  }
  const validation = validateRequestLabourWizard();
  if (!validation.valid) {
    routeToInvalidJobWizardStep(validation.step);
    return;
  }
  jobWizardSubmissionApproved = true;
  jobWizardSubmissionInProgress = true;
  const submitButton = document.getElementById("jobWizardSubmit");
  if (submitButton) {
    submitButton.disabled = true;
    submitButton.textContent = "Finding labour…";
  }
  try {
    jobForm.requestSubmit();
  } catch (error) {
    resetJobWizardSubmissionState();
    showToast(error?.message || "The labour request could not be submitted");
  }
}

document.getElementById("jobWizardContinue")?.addEventListener("click", () => {
  if (!jobWizardActive) return;
  if (jobWizardEnteredFromReview) {
    requestJobWizardNavigation(6);
    return;
  }
  if (!validateRequestLabourWizardStep(jobWizardStep, { report: true })) return;
  jobWizardCompleted.add(jobWizardStep);
  goToJobWizardStep(jobWizardStep + 1);
});

document
  .getElementById("jobWizardSubmit")
  ?.addEventListener("click", submitRequestLabourWizard);

document.getElementById("jobWizardReviewBody")?.addEventListener("click", (event) => {
  const edit = event.target.closest("[data-job-review-edit]");
  if (!edit) return;
  const step = Number(edit.dataset.jobReviewEdit);
  if (step < 1 || step > 5) return;
  jobWizardEnteredFromReview = true;
  goToJobWizardStep(step);
});

document.getElementById("jobWizardBack")?.addEventListener("click", () => {
  if (!jobWizardActive) return;
  requestJobWizardNavigation(jobWizardStep - 1);
});

document.querySelectorAll("[data-wizard-goto]").forEach((btn) => {
  btn.addEventListener("click", () => {
    if (!jobWizardActive) return;
    const step = Number(btn.dataset.wizardGoto);
    if (step === jobWizardStep || !jobWizardStepNavigable(step)) return;
    requestJobWizardNavigation(step);
  });
});

// Company wizard submission is permitted only after Step 6 final validation.
// This capture-phase listener still blocks every other wizard submission while
// allowing the approved event to continue through the form's existing ordered
// listeners (restoreFirstTradeRequirement, then the main creation handler).
document.addEventListener(
  "submit",
  (event) => {
    if (!jobWizardActive || event.target !== jobForm) return;
    if (
      jobWizardSubmissionApproved &&
      jobWizardSubmissionInProgress &&
      jobWizardStep === 6
    ) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
  },
  true,
);

// Block Enter-key implicit submission while in wizard mode.
jobForm?.addEventListener("keydown", (event) => {
  if (!jobWizardActive || event.key !== "Enter") return;
  const target = event.target;
  if (target instanceof HTMLTextAreaElement) return;
  if (target instanceof HTMLButtonElement) return;
  event.preventDefault();
});

let pendingTradeRequirements = [];
let activeTradeRequirementId = "";
let selectedJobCredentialIds = [];
let jobCredentialPickerOpen = false;
let jobCredentialBrowseAll = false;
let jobCredentialActiveIndex = -1;

function canonicalCredentialIds(ids = []) {
  const catalogue = window.OnSiteCredentials;
  if (!catalogue) return [];
  return [...new Set(Array.isArray(ids) ? ids : [])].filter((id) => catalogue.findById(id));
}

function credentialIdsForRequirement(requirement = {}) {
  const explicit = canonicalCredentialIds(requirement.requiredCredentialIds);
  if (explicit.length) return explicit;
  return window.OnSiteCredentials?.resolveLegacyIds(requirement.requiredQualifications) || [];
}

function credentialLabelsForRequirement(requirement = {}) {
  const labels = window.OnSiteCredentials?.labelsForIds(
    canonicalCredentialIds(requirement.requiredCredentialIds),
  ) || [];
  return labels.length ? labels : String(requirement.requiredQualifications || "")
    .split(/[,;]+/)
    .map((label) => label.trim())
    .filter(Boolean);
}

function syncJobCredentialMirror() {
  const input = document.getElementById("jobReqQuals");
  if (!input) return;
  input.value = (window.OnSiteCredentials?.labelsForIds(selectedJobCredentialIds) || []).join(", ");
}

function normalizeCredentialSearchText(value) {
  return String(value || "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function balancedCredentialSuggestions(credentials, catalogue, limit = 8) {
  const groups = catalogue.categoryOrder
    .map((category) => credentials
      .filter((credential) => credential.category === category)
      .sort((a, b) => Number(b.common) - Number(a.common)))
    .filter((group) => group.length);
  const suggestions = [];
  let row = 0;
  while (suggestions.length < limit && groups.some((group) => group[row])) {
    groups.forEach((group) => {
      if (suggestions.length < limit && group[row]) suggestions.push(group[row]);
    });
    row += 1;
  }
  return suggestions;
}

function rankCredentialSearchResults(credentials, query, tradeKey) {
  const normalizedQuery = normalizeCredentialSearchText(query);
  return credentials
    .map((credential, index) => {
      const label = normalizeCredentialSearchText(credential.label);
      const relevant = tradeKey && credential.tradeKeys.includes(tradeKey);
      const rank = label === normalizedQuery
        ? 0
        : label.startsWith(normalizedQuery)
          ? 1
          : label.includes(normalizedQuery)
            ? 2
            : relevant
              ? 3
              : 4;
      return { credential, index, rank };
    })
    .sort((a, b) => a.rank - b.rank || a.index - b.index)
    .map(({ credential }) => credential);
}

function jobCredentialOptionsModel() {
  const catalogue = window.OnSiteCredentials;
  const query = document.getElementById("jobCredentialSearch")?.value.trim() || "";
  if (!catalogue) return { groups: [], options: [], query };
  const tradeKey = window.OnSiteTaxonomy?.tradeKeyFor(
    document.getElementById("jobTrade")?.value,
  ) || "";
  if (query) {
    const options = rankCredentialSearchResults(
      catalogue.search(query, { limit: catalogue.credentials.length }),
      query,
      tradeKey,
    );
    return { groups: [{ label: "Search results", options }], options, query };
  }
  if (jobCredentialBrowseAll) {
    const groups = catalogue.categoryOrder
      .map((category) => ({
        label: catalogue.categoryLabels[category],
        options: catalogue.credentials.filter(
          (credential) => credential.requestable && credential.category === category,
        ),
      }))
      .filter((group) => group.options.length);
    return { groups, options: groups.flatMap((group) => group.options), query };
  }
  const allRelevant = catalogue.relevantToTrade(tradeKey);
  const suggested = balancedCredentialSuggestions(allRelevant, catalogue, 8);
  const suggestedIds = new Set(suggested.map((credential) => credential.id));
  const common = catalogue.common()
    .filter((credential) => !suggestedIds.has(credential.id))
    .slice(0, tradeKey ? 4 : 6);
  const tradeName = window.OnSiteTaxonomy?.findTrade(tradeKey)?.name || "";
  const groups = [
    ...(suggested.length ? [{ label: `Suggested for ${tradeName}`, options: suggested }] : []),
    { label: "Common site requirements", options: common },
  ].filter((group) => group.options.length);
  return { groups, options: groups.flatMap((group) => group.options), query };
}

function jobCredentialOptionHTML(credential, index, { showCategory = false } = {}) {
  const selected = selectedJobCredentialIds.includes(credential.id);
  return `<button class="credential-option${selected ? " is-selected" : ""}${index === jobCredentialActiveIndex ? " is-active" : ""}" type="button" role="option" aria-selected="${selected}" data-job-credential-id="${escapeHtml(credential.id)}">
    <span class="credential-option-label">${escapeHtml(credential.label)}</span>
    ${showCategory ? `<small>${escapeHtml(window.OnSiteCredentials?.categoryLabels[credential.category] || "")}</small>` : ""}
    <svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
  </button>`;
}

function renderJobCredentialPicker() {
  const picker = document.querySelector("[data-job-credential-picker]");
  const chips = document.getElementById("jobCredentialChips");
  const results = document.getElementById("jobCredentialResults");
  const search = document.getElementById("jobCredentialSearch");
  if (!picker || !chips || !results || !search) return;
  selectedJobCredentialIds = canonicalCredentialIds(selectedJobCredentialIds);
  syncJobCredentialMirror();
  const catalogue = window.OnSiteCredentials;
  chips.innerHTML = selectedJobCredentialIds
    .map((id) => catalogue?.findById(id))
    .filter(Boolean)
    .map((credential) => `<span class="credential-chip">${escapeHtml(credential.label)}<button type="button" data-remove-job-credential="${escapeHtml(credential.id)}" aria-label="Remove ${escapeHtml(credential.label)}">&times;</button></span>`)
    .join("");
  chips.classList.toggle("hidden", !selectedJobCredentialIds.length);
  search.setAttribute("aria-expanded", String(jobCredentialPickerOpen));
  results.classList.toggle("hidden", !jobCredentialPickerOpen);
  if (!jobCredentialPickerOpen) {
    results.innerHTML = "";
    picker.classList.remove("is-open");
    return;
  }
  picker.classList.add("is-open");
  const model = jobCredentialOptionsModel();
  if (jobCredentialActiveIndex >= model.options.length) jobCredentialActiveIndex = model.options.length - 1;
  let optionIndex = 0;
  const optionContent = model.options.length
    ? model.groups.map((group) => `<section class="credential-group"><h6>${escapeHtml(group.label)}</h6>${group.options.map((credential) => jobCredentialOptionHTML(credential, optionIndex++, { showCategory: Boolean(model.query) })).join("")}</section>`).join("")
    : `<div class="credential-empty"><strong>No catalogue matches</strong><span>Try another card, ticket or qualification name.</span></div>`;
  results.innerHTML = `<div class="credential-options-scroll" role="listbox" aria-label="Cards, tickets and qualifications">${optionContent}</div>
    <div class="credential-panel-actions">
      ${!model.query ? `<button class="credential-browse-toggle" type="button" data-job-credential-browse>${jobCredentialBrowseAll ? "Show suggestions" : "Browse all cards, tickets & qualifications →"}</button>` : ""}
      <button class="credential-missing-action" type="button" data-taxonomy-suggestion="credential">Can't find a card, ticket or qualification?</button>
    </div>`;
  results.querySelector(`[data-job-credential-id="${CSS.escape(model.options[jobCredentialActiveIndex]?.id || "")}"]`)?.scrollIntoView({ block: "nearest" });
}

function openJobCredentialPicker() {
  if (jobCredentialPickerOpen) return;
  jobCredentialPickerOpen = true;
  jobCredentialBrowseAll = false;
  jobCredentialActiveIndex = -1;
  closeAppPopovers(document.querySelector("[data-job-credential-picker]"));
  renderJobCredentialPicker();
}

function closeJobCredentialPicker() {
  if (!jobCredentialPickerOpen) return;
  jobCredentialPickerOpen = false;
  jobCredentialActiveIndex = -1;
  renderJobCredentialPicker();
}

function toggleJobCredential(id) {
  if (!window.OnSiteCredentials?.findById(id)) return;
  const keepBrowseAllOpen = jobCredentialBrowseAll;
  if (selectedJobCredentialIds.includes(id)) {
    selectedJobCredentialIds = selectedJobCredentialIds.filter((selectedId) => selectedId !== id);
  } else {
    selectedJobCredentialIds = [...selectedJobCredentialIds, id];
  }
  const search = document.getElementById("jobCredentialSearch");
  if (search) search.value = "";
  jobCredentialBrowseAll = keepBrowseAllOpen;
  jobCredentialActiveIndex = -1;
  document.getElementById("jobCredentialMessage")?.classList.add("hidden");
  renderJobCredentialPicker();
  setTradeRequirementMessage();
  updateTradeRequirementEditorState();
}

function setJobCredentialSelection(ids = []) {
  selectedJobCredentialIds = canonicalCredentialIds(ids);
  const search = document.getElementById("jobCredentialSearch");
  if (search) search.value = "";
  jobCredentialBrowseAll = false;
  jobCredentialActiveIndex = -1;
  renderJobCredentialPicker();
}

const jobCredentialPicker = document.querySelector("[data-job-credential-picker]");
const jobCredentialSearch = document.getElementById("jobCredentialSearch");
jobCredentialSearch?.addEventListener("focus", openJobCredentialPicker);
jobCredentialSearch?.addEventListener("click", openJobCredentialPicker);
jobCredentialSearch?.addEventListener("input", () => {
  jobCredentialPickerOpen = true;
  jobCredentialBrowseAll = false;
  jobCredentialActiveIndex = jobCredentialOptionsModel().options.length ? 0 : -1;
  document.getElementById("jobCredentialMessage")?.classList.add("hidden");
  renderJobCredentialPicker();
});
jobCredentialSearch?.addEventListener("keydown", (event) => {
  const model = jobCredentialOptionsModel();
  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
    event.preventDefault();
    if (!jobCredentialPickerOpen) openJobCredentialPicker();
    if (!model.options.length) return;
    const direction = event.key === "ArrowDown" ? 1 : -1;
    jobCredentialActiveIndex = (jobCredentialActiveIndex + direction + model.options.length) % model.options.length;
    renderJobCredentialPicker();
    return;
  }
  if (event.key === "Enter") {
    event.preventDefault();
    const credential = model.options[jobCredentialActiveIndex];
    if (credential) toggleJobCredential(credential.id);
    return;
  }
  if (event.key === "Escape") {
    event.preventDefault();
    closeJobCredentialPicker();
  }
});
jobCredentialPicker?.addEventListener("click", (event) => {
  const remove = event.target.closest("[data-remove-job-credential]");
  if (remove) {
    event.preventDefault();
    toggleJobCredential(remove.dataset.removeJobCredential);
    jobCredentialSearch?.focus();
    return;
  }
  const option = event.target.closest("[data-job-credential-id]");
  if (option) {
    toggleJobCredential(option.dataset.jobCredentialId);
    jobCredentialSearch?.focus();
    return;
  }
  if (event.target.closest("[data-job-credential-browse]")) {
    jobCredentialBrowseAll = !jobCredentialBrowseAll;
    jobCredentialActiveIndex = -1;
    renderJobCredentialPicker();
  }
});
document.addEventListener("pointerdown", (event) => {
  if (jobCredentialPickerOpen && !jobCredentialPicker?.contains(event.target)) {
    closeJobCredentialPicker();
  }
});
let tradeRequirementEditorOpen = false;
let pendingJobWizardNavigationStep = null;

function closeTradeRequirementGuard() {
  pendingJobWizardNavigationStep = null;
  hideWithMotion(document.getElementById("jobRequirementGuardModal"), null, {
    remove: true,
  });
}

function openTradeRequirementGuard(step) {
  document.getElementById("jobRequirementGuardModal")?.remove();
  pendingJobWizardNavigationStep = step;
  const modal = document.createElement("div");
  modal.id = "jobRequirementGuardModal";
  modal.className = "modal-overlay";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-labelledby", "jobRequirementGuardTitle");
  modal.innerHTML = `
    <div class="dispute-sheet jw-requirement-guard-sheet">
      <div class="dispute-sheet-header">
        <div>
          <h3 class="dispute-sheet-title" id="jobRequirementGuardTitle">Unsaved labour requirement</h3>
        </div>
        <button class="modal-close-btn" type="button" aria-label="Close and keep editing" data-requirement-guard-keep>×</button>
      </div>
      <div class="dispute-sheet-body">
        <p class="jw-requirement-guard-copy">Save or discard this requirement before leaving the Labour step.</p>
        <div class="jw-requirement-guard-actions">
          <button class="secondary-btn" type="button" data-requirement-guard-keep>Keep editing</button>
          <button class="secondary-btn" type="button" data-requirement-guard-discard>Discard changes</button>
          <button class="primary-btn" type="button" data-requirement-guard-save>Save requirement</button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(modal);
  modal.querySelectorAll("[data-requirement-guard-keep]").forEach((button) =>
    button.addEventListener("click", closeTradeRequirementGuard),
  );
  modal.addEventListener("click", (event) => {
    if (event.target === modal) closeTradeRequirementGuard();
  });
  modal.querySelector("[data-requirement-guard-discard]")?.addEventListener("click", () => {
    const targetStep = pendingJobWizardNavigationStep;
    closeTradeRequirementGuard();
    discardTradeRequirementEditorChanges();
    if (targetStep) requestJobWizardNavigation(targetStep);
  });
  modal.querySelector("[data-requirement-guard-save]")?.addEventListener("click", () => {
    const targetStep = pendingJobWizardNavigationStep;
    closeTradeRequirementGuard();
    if (saveTradeRequirement() && targetStep) {
      requestJobWizardNavigation(targetStep);
    }
  });
  modal.querySelector("[data-requirement-guard-keep]")?.focus();
}

function requestJobWizardNavigation(step) {
  if (
    jobWizardStep === 5 &&
    step !== 5 &&
    projectRequirementEditorState?.mode === "draft"
  ) {
    requestProjectRequirementEditorExit(() => requestJobWizardNavigation(step));
    return;
  }
  if (jobWizardStep === 2 && step !== 2 && tradeRequirementEditorHasUnsavedChanges()) {
    openTradeRequirementGuard(step);
    return;
  }
  if (step === 6 && jobWizardEnteredFromReview) {
    attemptReturnToJobWizardReview();
    return;
  }
  goToJobWizardStep(step);
}

function setTradeRequirementMessage(message = "", { allowDiscard = false } = {}) {
  const messageEl = document.getElementById("jobRequirementEditorMessage");
  const discard = document.getElementById("jobDiscardTradeRequirement");
  if (messageEl) {
    messageEl.textContent = message;
    messageEl.classList.toggle("hidden", !message);
  }
  if (discard) {
    discard.classList.toggle(
      "hidden",
      !(allowDiscard || activeTradeRequirementId),
    );
  }
}

function savedLabourRequirementValidationIssue() {
  for (const requirement of pendingTradeRequirements) {
    if (!requirement.trade) return { requirement, message: "Select a trade." };
    if (!requirement.specialism) {
      return { requirement, message: "Select a role / specialism." };
    }
    if (!requirement.workActivity) {
      return { requirement, message: "Enter the work activity." };
    }
    if (!Number.isFinite(Number(requirement.quantity)) || Number(requirement.quantity) < 1) {
      return { requirement, message: "Enter at least one worker." };
    }
    if (!Number.isFinite(Number(requirement.budgetMax)) || Number(requirement.budgetMax) <= 0) {
      return { requirement, message: "Enter the daily labour rate." };
    }
  }
  return null;
}

function validateLabourWizardStepNavigation({ report = true } = {}) {
  if (tradeRequirementEditorHasUnsavedChanges()) {
    if (report) {
      setTradeRequirementMessage(
        "Save or discard this requirement before continuing.",
        { allowDiscard: true },
      );
      updateTradeRequirementEditorState();
      document.getElementById("jobAddTradeBtn")?.focus();
    }
    return false;
  }
  if (!pendingTradeRequirements.length) {
    if (report) {
      tradeRequirementEditorOpen = true;
      updateTradeRequirementEditorState();
      setTradeRequirementMessage(
        "Add and save at least one labour requirement to continue.",
      );
      document.getElementById("jobTrade")?.focus();
    }
    return false;
  }
  const issue = savedLabourRequirementValidationIssue();
  if (issue) {
    if (report) {
      openTradeRequirementEditor(issue.requirement);
      setTradeRequirementMessage(issue.message, { allowDiscard: true });
      showToast(issue.message);
    }
    return false;
  }
  if (report) setTradeRequirementMessage();
  return true;
}

document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && document.getElementById("jobRequirementGuardModal")) {
    closeTradeRequirementGuard();
  }
});

function updateAssignmentTypeForm() {
  const type = normalizeAssignmentType(
    document.getElementById("jobAssignmentType")?.value,
  );
  const ongoing = type === "ongoing_placement";
  const endInput = document.getElementById("jobEndDate");
  const endRequired = document.getElementById("jobEndDateRequired");
  const siteAddress = document.getElementById("jobSiteAddress");
  const noFixedEnd = document.getElementById("jobNoFixedEndDate");
  const noFixedWrap = document.getElementById("jobNoFixedEndWrap");
  const vehicleWrap = document.getElementById("jobVehicleWrap");
  if (noFixedWrap) noFixedWrap.classList.remove("hidden");
  if (vehicleWrap) vehicleWrap.classList.toggle("hidden", !ongoing);
  if (endInput) {
    const noFixed = !!noFixedEnd?.checked;
    endInput.required = !noFixed;
    endInput.disabled = noFixed;
    endInput.classList.remove("hidden");
    endInput.closest(".jw-end-date-field")?.classList.toggle("is-disabled", noFixed);
    if (endRequired) endRequired.hidden = noFixed;
    if (noFixed) endInput.value = "";
  }
  if (siteAddress) siteAddress.required = true;
}

const JOB_ACCOMMODATION_ARRANGEMENTS = new Set([
  "company_provided",
  "nightly_allowance",
]);

function accommodationArrangementFor(record = {}) {
  const explicit = String(record.accommodationArrangement || "");
  if (JOB_ACCOMMODATION_ARRANGEMENTS.has(explicit)) return explicit;
  if (Number(record.accommodationAllowancePerNight) > 0) {
    return "nightly_allowance";
  }
  return record.accommodationPaid ? "company_provided" : "";
}

function normalizedAccommodationState(record = {}) {
  const accommodationArrangement = accommodationArrangementFor(record);
  const allowance = Number(record.accommodationAllowancePerNight);
  return {
    accommodationPaid: !!accommodationArrangement,
    accommodationArrangement,
    accommodationAllowancePerNight:
      accommodationArrangement === "nightly_allowance" && allowance > 0
        ? Math.round(allowance)
        : null,
  };
}

function accommodationSummaryFor(record = {}) {
  const accommodationArrangement = accommodationArrangementFor(record);
  if (!accommodationArrangement) return "";
  return accommodationArrangement === "nightly_allowance" &&
    Number(record.accommodationAllowancePerNight) > 0
    ? `${formatMoney(record.accommodationAllowancePerNight)}/night accommodation`
    : "Accommodation provided";
}

function selectedJobAccommodationArrangement() {
  return (
    document.querySelector('input[name="jobAccommodationArrangement"]:checked')
      ?.value || ""
  );
}

function setJobAccommodationArrangement(value) {
  const arrangement = JOB_ACCOMMODATION_ARRANGEMENTS.has(value)
    ? value
    : "";
  document
    .querySelectorAll('input[name="jobAccommodationArrangement"]')
    .forEach((input) => {
      input.checked = input.value === arrangement;
    });
}

function updateAccommodationForm() {
  const paid = !!document.getElementById("jobAccommodationPaid")?.checked;
  const settings = document.getElementById("jobAccommodationArrangementWrap");
  let arrangement = selectedJobAccommodationArrangement();
  if (paid && !JOB_ACCOMMODATION_ARRANGEMENTS.has(arrangement)) {
    arrangement = "company_provided";
    setJobAccommodationArrangement(arrangement);
  }
  const allowanceWrap = document.getElementById("jobAccommodationAllowanceWrap");
  const allowance = document.getElementById("jobAccommodationAllowance");
  settings?.classList.toggle("hidden", !paid);
  allowanceWrap?.classList.toggle(
    "hidden",
    !paid || arrangement !== "nightly_allowance",
  );
  if (allowance) {
    const nightlyAllowanceSelected =
      paid && arrangement === "nightly_allowance";
    allowance.required = nightlyAllowanceSelected;
    if (nightlyAllowanceSelected && !allowance.value.trim()) {
      allowance.value = "0";
    }
  }
  renderJobPricingBreakdown();
}

function updateOvertimeForm() {
  const available = !!document.getElementById("jobOvertimeAvailable")?.checked;
  const wrap = document.getElementById("jobOvertimeRatesWrap");
  if (wrap) wrap.classList.toggle("hidden", !available);
  renderJobPricingBreakdown();
}

document
  .getElementById("jobAssignmentType")
  ?.addEventListener("change", updateAssignmentTypeForm);
document
  .getElementById("jobNoFixedEndDate")
  ?.addEventListener("change", updateAssignmentTypeForm);
document
  .getElementById("jobAccommodationPaid")
  ?.addEventListener("change", updateAccommodationForm);
document
  .querySelectorAll('input[name="jobAccommodationArrangement"]')
  .forEach((input) => input.addEventListener("change", updateAccommodationForm));
document
  .getElementById("jobAccommodationAllowance")
  ?.addEventListener("focus", (event) => {
    const input = event.currentTarget;
    if (input.value.trim() && Number(input.value) === 0) {
      requestAnimationFrame(() => input.select());
    }
  });
document
  .getElementById("jobOvertimeAvailable")
  ?.addEventListener("change", updateOvertimeForm);
updateAssignmentTypeForm();
updateAccommodationForm();
updateOvertimeForm();

function selectedJobWorkingDays() {
  return normalizeWorkingDays(
    Array.from(document.querySelectorAll('input[name="jobWorkingDays"]:checked')).map(
      (input) => input.value,
    ),
  );
}

function setSchedulePayMessage(id, message = "") {
  const element = document.getElementById(id);
  if (!element) return;
  element.textContent = message;
  element.classList.toggle("hidden", !message);
}

function clearSchedulePayValidation() {
  document.getElementById("jobEndDate")?.setCustomValidity("");
  setSchedulePayMessage("jobWorkingDaysMessage");
  setSchedulePayMessage("jobScheduleStepMessage");
}

function validateSchedulePayWizardStep({ report = true } = {}) {
  if (report) clearSchedulePayValidation();
  const startInput = document.getElementById("jobStart");
  const endInput = document.getElementById("jobEndDate");
  const noFixedEndDate = !!document.getElementById("jobNoFixedEndDate")?.checked;
  const startDate = startInput?.value?.slice(0, 10) || "";
  const endDate = noFixedEndDate ? "" : endInput?.value || "";

  if (startDate && endDate) {
    const start = dateOnlyMs(startDate);
    const end = dateOnlyMs(endDate);
    if (start !== null && end !== null && end < start) {
      const message = "Estimated end date must be on or after the project start date.";
      if (report) {
        endInput?.setCustomValidity(message);
        setSchedulePayMessage("jobScheduleStepMessage", message);
        endInput?.reportValidity();
        endInput?.focus();
      }
      return false;
    }
  }

  const selectedWorkingDayCount = document.querySelectorAll(
    'input[name="jobWorkingDays"]:checked',
  ).length;
  if (!selectedWorkingDayCount) {
    if (report) {
      setSchedulePayMessage(
        "jobWorkingDaysMessage",
        "Select at least one working day.",
      );
      document.querySelector('input[name="jobWorkingDays"]')?.focus();
    }
    return false;
  }

  return true;
}

function openNativePickerFromField(input, event) {
  if (
    event.button !== 0 ||
    input.disabled ||
    input.readOnly ||
    typeof input.showPicker !== "function"
  ) {
    return;
  }
  input.focus({ preventScroll: true });
  try {
    input.showPicker();
    event.preventDefault();
  } catch {
    // Preserve the browser's normal native-input behaviour as the fallback.
  }
}

["jobStart", "jobEndDate", "jobShiftStart", "jobShiftFinish"].forEach((id) => {
  const input = document.getElementById(id);
  if (["jobStart", "jobEndDate"].includes(id)) {
    input?.addEventListener("input", clearSchedulePayValidation);
  }
  input?.addEventListener("click", (event) => {
    openNativePickerFromField(input, event);
  });
});
["jobStart", "jobEndDate", "jobShiftStart", "jobShiftFinish"].forEach((id) => {
  document.getElementById(id)?.addEventListener("change", (event) => {
    const control = event.currentTarget;
    if (control.value) {
      requestAnimationFrame(() => control.blur());
    }
  });
});
document.getElementById("jobNoFixedEndDate")?.addEventListener("change", () => {
  clearSchedulePayValidation();
});
document.querySelectorAll('input[name="jobWorkingDays"]').forEach((input) => {
  input.addEventListener("change", clearSchedulePayValidation);
});

// ─── Multi-trade labour requirement builder ───────────────

function normalizeLabourSchedule(periods = []) {
  return (periods || [])
    .map((period) => ({
      id: period.id || createId(),
      startDate: String(period.startDate || "").slice(0, 10),
      endDate: String(period.endDate || "").slice(0, 10),
      quantity: Math.max(1, Number(period.quantity) || 1),
      phase: String(period.phase || period.notes || "").trim(),
      notes: String(period.notes || period.phase || "").trim(),
    }))
    .filter((period) => period.startDate || period.endDate || period.quantity)
    .sort((a, b) => dateOnlyMs(a.startDate) - dateOnlyMs(b.startDate));
}

function validateLabourSchedule(periods = [], { projectStart = "", projectEnd = "", noFixedEndDate = false } = {}) {
  const normalized = normalizeLabourSchedule(periods);
  for (const period of normalized) {
    if (!period.startDate || !period.endDate) return "Each labour schedule period needs a start and end date";
    const start = dateOnlyMs(period.startDate);
    const end = dateOnlyMs(period.endDate);
    if (start === null || end === null) return "Use valid dates for each labour schedule period";
    if (end < start) return "Labour schedule end dates must be after start dates";
    if (!Number.isFinite(Number(period.quantity)) || Number(period.quantity) < 1) return "Labour schedule quantities must be at least 1";
    const projectStartMs = dateOnlyMs(projectStart);
    const projectEndMs = noFixedEndDate ? null : dateOnlyMs(projectEnd);
    if (projectStartMs !== null && start < projectStartMs) return "Labour schedule periods must start within the project dates";
    if (projectEndMs !== null && end > projectEndMs) return "Labour schedule periods must end within the project dates";
  }
  for (let i = 1; i < normalized.length; i++) {
    if (dateOnlyMs(normalized[i].startDate) <= dateOnlyMs(normalized[i - 1].endDate)) {
      return "Labour schedule periods cannot overlap";
    }
  }
  return "";
}

function readTradeReqInputs() {
  syncDailyLabourRateFields();
  const budgetMaxRaw = Number(document.getElementById("jobBudgetMax")?.value);
  const budgetMax =
    Number.isFinite(budgetMaxRaw) && budgetMaxRaw > 0
      ? Math.round(budgetMaxRaw)
      : null;
  const workerReceivesFullAdvertisedRate =
    !!document.getElementById("jobWorkerReceivesFullRate")?.checked;
  const accommodationPaid = !!document.getElementById("jobAccommodationPaid")?.checked;
  const accommodationArrangement = accommodationPaid
    ? selectedJobAccommodationArrangement() || "company_provided"
    : "";
  const accommodationAllowanceRaw = Number(
    document.getElementById("jobAccommodationAllowance")?.value,
  );
  const accommodationAllowancePerNight =
    accommodationPaid &&
    accommodationArrangement === "nightly_allowance" &&
    Number.isFinite(accommodationAllowanceRaw) &&
    accommodationAllowanceRaw > 0
      ? Math.round(accommodationAllowanceRaw)
      : null;
  const trade = document.getElementById("jobTrade")?.value || "";
  const specialism = document.getElementById("jobSpecialism")?.value || "";
  return {
    id: createId(),
    trade,
    tradeKey: window.OnSiteTaxonomy?.tradeKeyFor(trade) || "",
    specialism,
    roleKey: window.OnSiteTaxonomy?.roleKeyFor(trade, specialism) || "",
    workActivity: document.getElementById("workActivity")?.value.trim() || "",
    quantity: Math.max(1, Number(document.getElementById("jobQuantity")?.value) || 1),
    requiredCredentialIds: [...selectedJobCredentialIds],
    requiredQualifications:
      (window.OnSiteCredentials?.labelsForIds(selectedJobCredentialIds) || []).join(", "),
    budgetMin: budgetMax,
    budgetMax,
    workerReceivesFullAdvertisedRate,
    accommodationPaid,
    accommodationArrangement,
    accommodationAllowancePerNight,
  };
}

function tradeReqHasCoreFields(req) {
  return !!(
    req?.trade &&
    req?.specialism &&
    req?.workActivity &&
    req?.budgetMax
  );
}

function labourRequirementKey(req) {
  const overtimeRates = req?.overtimeRates || {};
  const scheduleKey = normalizeLabourSchedule(req?.labourSchedule)
    .map((period) => `${period.startDate}:${period.endDate}:${period.quantity}:${period.phase || ""}`)
    .join(",");
  return [
    req?.tradeKey || req?.trade || "",
    req?.roleKey || req?.specialism || "",
    req?.grade || "",
    req?.workActivity || "",
    canonicalCredentialIds(req?.requiredCredentialIds).sort().join(",") ||
      req?.requiredQualifications ||
      "",
    Number(req?.quantity || 1),
    Number(req?.budgetMax || 0),
    req?.workerReceivesFullAdvertisedRate !== false,
    !!req?.overtimeAvailable,
    overtimeRates.afterStandardHours || "standard",
    overtimeRates.saturday || "standard",
    overtimeRates.sunday || "standard",
    !!req?.accommodationPaid,
    accommodationArrangementFor(req),
    Number(req?.accommodationAllowancePerNight || 0),
    scheduleKey,
  ].join("|");
}

function sameTradeRequirement(a, b) {
  return labourRequirementKey(a) === labourRequirementKey(b);
}

function dedupeLabourRequirements(requirements) {
  const seen = new Map();
  (requirements || []).forEach((req) => {
    const key = labourRequirementKey(req);
    if (!seen.has(key)) seen.set(key, req);
  });
  return Array.from(seen.values());
}

function requestLabourEstimateRequirements() {
  const current = readTradeReqInputs();
  const requirements = [...pendingTradeRequirements];
  if (
    (current.trade ||
      current.specialism ||
      current.workActivity ||
      current.quantity > 1 ||
      current.budgetMax) &&
    !requirements.some((req) => sameTradeRequirement(req, current))
  ) {
    requirements.push(current);
  }
  return requirements.length ? requirements : [current];
}

function syncDailyLabourRateFields() {
  const rateInput = document.getElementById("jobBudgetMax");
  const minInput = document.getElementById("jobBudgetMin");
  if (rateInput && minInput) minInput.value = rateInput.value;
}

function buildRequestLabourPricingModel(requirements = []) {
  const visibleReqs = requirements.map((req, index) => ({
    trade: req.trade || "",
    specialism: req.specialism || "",
    grade: req.grade || "",
    label:
      [req.trade, req.specialism].filter(Boolean).join(" / ") ||
      `Labour requirement ${index + 1}`,
    quantity: Math.max(1, Number(req.quantity) || 1),
    rate: Math.max(0, Number(req.budgetMax) || 0),
    workerReceivesFullAdvertisedRate: req.workerReceivesFullAdvertisedRate !== false,
    accommodationArrangement: accommodationArrangementFor(req),
    accommodationAllowance:
      accommodationArrangementFor(req) === "nightly_allowance"
        ? Math.max(0, Number(req.accommodationAllowancePerNight) || 0)
        : 0,
  }));

  // TODO: Replace these provisional display-only percentages with configured
  // commercial rates when the real checkout/invoicing layer exists.
  const serviceFeePct = 0.15;
  const vatPct = 0.2;
  const pricedRequirements = visibleReqs.map((req) => {
    const rate = req.rate;
    const accommodationAllowance = req.accommodationAllowance;
    const workerReceivesFullRate = req.workerReceivesFullAdvertisedRate !== false;
    const workerReceives = workerReceivesFullRate
      ? rate
      : Math.max(0, Math.floor(rate / (1 + serviceFeePct)));
    const serviceFee = workerReceivesFullRate
      ? Math.round(rate * serviceFeePct)
      : Math.max(0, rate - workerReceives);
    const companyDayRate = workerReceivesFullRate ? rate + serviceFee : rate;
    const vat = Math.round(companyDayRate * vatPct);
    const totalPerWorker = companyDayRate + vat;
    const requirementTotal = totalPerWorker * req.quantity;
    const accommodationTotal = accommodationAllowance * req.quantity;
    return {
      ...req,
      workerReceivesFullRate,
      workerReceives,
      serviceFee,
      companyDayRate,
      vat,
      totalPerWorker,
      requirementTotal,
      accommodationTotal,
    };
  });
  return {
    requirements: pricedRequirements,
    totalWorkers: pricedRequirements.reduce((sum, req) => sum + req.quantity, 0),
    totalWorkerLabour: pricedRequirements.reduce(
      (sum, req) => sum + req.workerReceives * req.quantity,
      0,
    ),
    totalServiceFee: pricedRequirements.reduce(
      (sum, req) => sum + req.serviceFee * req.quantity,
      0,
    ),
    totalAccommodation: pricedRequirements.reduce(
      (sum, req) => sum + req.accommodationTotal,
      0,
    ),
    totalVat: pricedRequirements.reduce(
      (sum, req) => sum + req.vat * req.quantity,
      0,
    ),
    totalDailyCost: pricedRequirements.reduce(
      (sum, req) => sum + req.requirementTotal,
      0,
    ),
  };
}

function renderJobPricingBreakdown() {
  const panel = document.getElementById("jobPricingBreakdown");
  if (!panel) return;
  syncDailyLabourRateFields();
  const wizardPricing = jobWizardActive;
  const requirements = wizardPricing
    ? [...pendingTradeRequirements]
    : requestLabourEstimateRequirements();
  const wizardMount = document.getElementById("jobPricingBreakdownWizardMount");
  panel.classList.toggle("jw-pricing-panel--wizard", wizardPricing);
  wizardMount?.classList.toggle("hidden", wizardPricing && !requirements.length);
  if (wizardPricing && !requirements.length) {
    panel.classList.add("hidden");
    panel.replaceChildren();
    return;
  }
  panel.classList.remove("hidden");
  const pricing = buildRequestLabourPricingModel(requirements);
  const visibleReqs = pricing.requirements;
  const rows = visibleReqs
    .map((req) => {
      const {
        rate,
        accommodationAllowance,
        accommodationTotal,
        workerReceivesFullRate,
        workerReceives,
        serviceFee,
        vat,
        totalPerWorker,
        requirementTotal,
      } = req;
      if (wizardPricing) {
        const roleDetails = [req.specialism, req.grade].filter(Boolean).join(" · ");
        return `
          <div class="jw-price-row">
            <div class="jw-price-identity">
              <strong>${escapeHtml(req.trade || req.label)}</strong>
              ${roleDetails ? `<span>${escapeHtml(roleDetails)}</span>` : ""}
              <span class="jw-price-rate-summary">${req.quantity} worker${req.quantity === 1 ? "" : "s"} &times; ${formatMoney(rate)}/day</span>
            </div>
            <div class="jw-price-breakdown">
              <span class="jw-price-breakdown-label">Per worker / day</span>
              <div class="jw-price-lines">
                <span>Worker receives <strong>${formatMoney(workerReceives)}</strong></span>
                <span>OnSite service fee ${workerReceivesFullRate ? "(added separately)" : "(deducted from rate)"} <strong>${formatMoney(serviceFee)}</strong></span>
                <span>VAT <strong>${formatMoney(vat)}</strong></span>
                <span class="jw-price-company-cost">Company cost / worker <strong>${formatMoney(totalPerWorker)}</strong></span>
              </div>
              <div class="jw-price-requirement-total">
                <span>${req.quantity} worker${req.quantity === 1 ? "" : "s"} &times; ${formatMoney(totalPerWorker)}/day</span>
                <strong>${formatMoney(requirementTotal)}/day</strong>
              </div>
              ${accommodationAllowance > 0 ? `<div class="jw-price-accommodation"><span>Accommodation</span><div><strong>${formatMoney(accommodationAllowance)}/night per worker</strong><small>${req.quantity} worker${req.quantity === 1 ? "" : "s"} &times; ${formatMoney(accommodationAllowance)}/night = ${formatMoney(accommodationTotal)}/night · Added to the company invoice without an OnSite service fee.</small></div></div>` : req.accommodationArrangement === "company_provided" ? `<div class="jw-price-accommodation"><span>Accommodation</span><strong>Company provided</strong></div>` : ""}
            </div>
          </div>`;
      }
      return `
        <div class="jw-price-row">
          <div>
            <strong>${escapeHtml(req.label)}</strong>
            <span>${req.quantity} worker${req.quantity === 1 ? "" : "s"}</span>
          </div>
          <div class="jw-price-lines">
            <span>Daily labour rate <strong>${formatMoney(rate)}</strong></span>
            <span>Worker receives <strong>${formatMoney(workerReceives)}</strong></span>
            <span>OnSite service fee ${workerReceivesFullRate ? "(added separately)" : "(deducted from rate)"} <strong>${formatMoney(serviceFee)}</strong></span>
            <span>VAT <strong>${formatMoney(vat)}</strong></span>
            <span>Total per worker <strong>${formatMoney(totalPerWorker)}</strong></span>
            <span>Total daily cost <strong>${formatMoney(requirementTotal)}</strong></span>
            ${accommodationAllowance > 0 ? `<span>Accommodation allowance <strong>${formatMoney(accommodationAllowance)}/night per worker</strong></span>` : req.accommodationArrangement === "company_provided" ? `<span>Accommodation <strong>Company provided</strong></span>` : ""}
          </div>
        </div>`;
    })
    .join("");

  if (wizardPricing) {
    panel.innerHTML = `
      <div class="jw-estimate-head">
        <div>
          <h4>Estimated labour cost</h4>
          <p>Based on your saved labour requirements. Final invoices are based on approved attendance and any applicable adjustments.</p>
        </div>
      </div>
      <div class="jw-price-list">${rows}</div>
      <div class="jw-price-total">
        <span>Total workers <strong>${pricing.totalWorkers}</strong></span>
        <span>Labour requirements <strong>${visibleReqs.length}</strong></span>
        <span class="jw-price-grand-total">Estimated daily labour cost <strong>${formatMoney(pricing.totalDailyCost)}</strong></span>
        ${pricing.totalAccommodation ? `<span class="jw-price-accommodation-total">Nightly accommodation allowances <strong>${formatMoney(pricing.totalAccommodation)}/night</strong></span>` : ""}
      </div>`;
    return;
  }

  panel.innerHTML = `
    <div class="jw-price-head">
      <div>
        <strong>Live pricing breakdown</strong>
        <span>Daily totals shown are what you’ll be charged, unless deductions, overtime or allowances apply. Final invoices are based on approved attendance.</span>
      </div>
    </div>
    <div class="jw-price-list">${rows}</div>
    ${
      visibleReqs.some((req) => req.accommodationAllowance > 0)
        ? `<p class="jw-price-note">Accommodation is added to the company invoice without an OnSite service fee.</p>`
        : ""
    }
    <div class="jw-price-total">
      <span>Total workers: <strong>${pricing.totalWorkers}</strong></span>
      <span>Total trades / labour requirements: <strong>${visibleReqs.length}</strong></span>
      <span>Total daily cost for all workers: <strong>${formatMoney(pricing.totalDailyCost)}</strong></span>
      ${pricing.totalAccommodation ? `<span>Nightly accommodation allowances: <strong>${formatMoney(pricing.totalAccommodation)}/night</strong></span>` : ""}
    </div>`;
}

function buildLabourRequirementsFromForm(shared = {}) {
  const current = readTradeReqInputs();
  const requirements = [...pendingTradeRequirements];
  if (
    tradeReqHasCoreFields(current) &&
    !requirements.some((req) => sameTradeRequirement(req, current))
  ) {
    requirements.push(current);
  }
  const base = requirements.length ? requirements : [current];
  return dedupeLabourRequirements(base)
    .filter((req) => req.trade || req.specialism || req.workActivity)
    .map((req, index) => ({
      id: req.id || `${createId()}-${index}`,
      trade: req.trade || "",
      tradeKey:
        req.tradeKey || window.OnSiteTaxonomy?.tradeKeyFor(req.trade) || "",
      specialism: req.specialism || "",
      roleKey:
        req.roleKey ||
        window.OnSiteTaxonomy?.roleKeyFor(req.trade, req.specialism) ||
        "",
      grade: req.grade || "",
      requiredQualifications: req.requiredQualifications || "",
      requiredCredentialIds: canonicalCredentialIds(req.requiredCredentialIds),
      workActivity: req.workActivity || "",
      quantity: Math.max(1, Number(req.quantity) || 1),
      budgetMin: req.budgetMin ?? req.budgetMax ?? shared.budgetMin ?? null,
      budgetMax: req.budgetMax ?? shared.budgetMax ?? null,
      saturdayRate: req.saturdayRate ?? shared.saturdayRate ?? req.budgetMax ?? shared.budgetMax ?? null,
      sundayRate: req.sundayRate ?? shared.sundayRate ?? req.budgetMax ?? shared.budgetMax ?? null,
      workerReceivesFullAdvertisedRate:
        req.workerReceivesFullAdvertisedRate ??
        shared.workerReceivesFullAdvertisedRate ??
        true,
      ...normalizedAccommodationState({
        accommodationPaid: req.accommodationPaid ?? shared.accommodationPaid,
        accommodationArrangement:
          req.accommodationArrangement ?? shared.accommodationArrangement,
        accommodationAllowancePerNight:
          req.accommodationAllowancePerNight ??
          shared.accommodationAllowancePerNight,
      }),
      workingDays: normalizeWorkingDays(shared.workingDays),
      shiftStartTime: shared.shiftStartTime || "",
      shiftFinishTime: shared.shiftFinishTime || "",
    }));
}

function applyTradeReqToInputs(req) {
  jobLabourMoreOptionsOpen = labourRequirementHasAdvancedOptions(req);
  const tradeSelect = document.getElementById("jobTrade");
  const spec = document.getElementById("jobSpecialism");
  if (tradeSelect) {
    window.OnSiteTaxonomy?.populateTradeSelect(tradeSelect, {
      selectedValue: req.trade || req.tradeKey || "",
      preserveUnknown: true,
    });
  }
  if (spec) {
    window.OnSiteTaxonomy?.populateRoleSelect(
      spec,
      tradeSelect?.value || req.trade || req.tradeKey || "",
      { selectedValue: req.specialism || req.roleKey || "", preserveUnknown: true },
    );
  }
  const act = document.getElementById("workActivity");
  if (act) act.value = req.workActivity;
  const qty = document.getElementById("jobQuantity");
  if (qty) qty.value = String(req.quantity);
  setJobCredentialSelection(credentialIdsForRequirement(req));
  const rate = document.getElementById("jobBudgetMax");
  if (rate) rate.value = req.budgetMax || "";
  const fullRate = document.getElementById("jobWorkerReceivesFullRate");
  if (fullRate) fullRate.checked = req.workerReceivesFullAdvertisedRate !== false;
  const accommodationState = normalizedAccommodationState(req);
  const accommodation = document.getElementById("jobAccommodationPaid");
  if (accommodation) accommodation.checked = accommodationState.accommodationPaid;
  setJobAccommodationArrangement(accommodationState.accommodationArrangement);
  const accommodationAllowance = document.getElementById("jobAccommodationAllowance");
  if (accommodationAllowance) {
    accommodationAllowance.value =
      accommodationState.accommodationAllowancePerNight || "";
  }
  updateAccommodationForm();
  syncJobLabourDisclosureState();
}

function clearTradeReqInputs() {
  applyTradeReqToInputs({
    trade: "",
    specialism: "",
    workActivity: "",
    quantity: 1,
    requiredQualifications: "",
    requiredCredentialIds: [],
    budgetMax: "",
    workerReceivesFullAdvertisedRate: true,
    accommodationPaid: false,
    accommodationArrangement: "",
    accommodationAllowancePerNight: null,
  });
}

function tradeRequirementHasMeaningfulInput(req = readTradeReqInputs()) {
  return !!(
    req.trade ||
    req.specialism ||
    req.workActivity ||
    credentialIdsForRequirement(req).length ||
    req.requiredQualifications ||
    req.budgetMax ||
    Number(req.quantity || 1) !== 1 ||
    req.workerReceivesFullAdvertisedRate === false ||
    req.accommodationPaid
  );
}

function tradeRequirementEditorHasUnsavedChanges() {
  if (!tradeRequirementEditorOpen) return false;
  const current = readTradeReqInputs();
  if (!activeTradeRequirementId) return tradeRequirementHasMeaningfulInput(current);
  const saved = pendingTradeRequirements.find(
    (requirement) => requirement.id === activeTradeRequirementId,
  );
  return !saved || !sameTradeRequirement(saved, current);
}

function updateTradeRequirementEditorState() {
  const hasRequirements = pendingTradeRequirements.length > 0;
  const editor = document.getElementById("jobRequirementEditor");
  const emptyState = document.getElementById("jobLabourEmptyState");
  const savedSection = document.getElementById("jobSavedRequirementsSection");
  const preferredSection = document.getElementById("jobPreferredWorkersWrap");
  const addAnother = document.getElementById("jobAddAnotherRequirement");
  const editorTitle = document.getElementById("jobRequirementEditorTitle");
  const editorMode = document.getElementById("jobRequirementEditorMode");
  const saveButton = document.getElementById("jobAddTradeBtn");
  const discardButton = document.getElementById("jobDiscardTradeRequirement");
  const editorVisible = !jobWizardActive || tradeRequirementEditorOpen;
  editor?.classList.toggle("hidden", !editorVisible);
  emptyState?.classList.toggle(
    "hidden",
    !jobWizardActive || hasRequirements || editorVisible,
  );
  savedSection?.classList.toggle(
    "hidden",
    !hasRequirements || (jobWizardActive && editorVisible),
  );
  if (preferredSection && jobWizardActive) {
    preferredSection.classList.toggle("hidden", !hasRequirements || editorVisible);
  }
  addAnother?.classList.toggle("hidden", editorVisible);
  if (editorTitle) {
    editorTitle.textContent = activeTradeRequirementId
      ? "Edit requirement"
      : "New requirement";
  }
  editorMode?.classList.toggle("hidden", !activeTradeRequirementId);
  if (saveButton) {
    saveButton.textContent = activeTradeRequirementId
      ? "Save changes"
      : "Save requirement";
  }
  const hasUnsavedChanges = editorVisible && tradeRequirementEditorHasUnsavedChanges();
  if (discardButton) {
    discardButton.textContent = activeTradeRequirementId || hasUnsavedChanges
      ? "Discard changes"
      : "Cancel";
    discardButton.classList.toggle(
      "hidden",
      !jobWizardActive && !(activeTradeRequirementId || hasUnsavedChanges),
    );
  }
  const formWrap = document.getElementById("formJob");
  formWrap?.classList.toggle(
    "jw-requirement-editor-active",
    jobWizardActive && jobWizardStep === 2 && editorVisible,
  );
  formWrap?.classList.toggle(
    "jw-has-unsaved-requirement",
    jobWizardActive && jobWizardStep === 2 && hasUnsavedChanges,
  );
}

function openTradeRequirementEditor(requirement = null) {
  activeTradeRequirementId = requirement?.id || "";
  tradeRequirementEditorOpen = true;
  if (requirement) applyTradeReqToInputs(requirement);
  else clearTradeReqInputs();
  setTradeRequirementMessage();
  updateTradeRequirementEditorState();
  requestAnimationFrame(() => document.getElementById("jobTrade")?.focus());
}

function discardTradeRequirementEditorChanges() {
  activeTradeRequirementId = "";
  clearTradeReqInputs();
  tradeRequirementEditorOpen = !jobWizardActive;
  setTradeRequirementMessage();
  syncTradeReqBuilderState();
}

function failTradeRequirementSave(fieldId, message) {
  setTradeRequirementMessage(message, { allowDiscard: true });
  const field = document.getElementById(fieldId);
  field?.focus();
  if (field?.reportValidity && !field.checkValidity()) field.reportValidity();
  showToast(message);
  return false;
}

function saveTradeRequirement() {
  const req = readTradeReqInputs();
  if (!req.trade) return failTradeRequirementSave("jobTrade", "Select a trade first");
  if (!req.specialism) {
    return failTradeRequirementSave("jobSpecialism", "Select a role / specialism");
  }
  if (!req.workActivity) {
    return failTradeRequirementSave("workActivity", "Enter the work activity");
  }
  const quantity = Number(document.getElementById("jobQuantity")?.value);
  if (!Number.isFinite(quantity) || quantity < 1) {
    return failTradeRequirementSave("jobQuantity", "Enter at least one worker");
  }
  if (!req.budgetMax) {
    return failTradeRequirementSave("jobBudgetMax", "Enter the daily labour rate");
  }
  if (
    req.accommodationPaid &&
    req.accommodationArrangement === "nightly_allowance" &&
    !req.accommodationAllowancePerNight
  ) {
    return failTradeRequirementSave(
      "jobAccommodationAllowance",
      "Enter a nightly allowance greater than £0.",
    );
  }
  const duplicate = pendingTradeRequirements.some(
    (existing) =>
      existing.id !== activeTradeRequirementId &&
      sameTradeRequirement(existing, req),
  );
  if (duplicate) {
    setTradeRequirementMessage("This labour requirement has already been added", {
      allowDiscard: true,
    });
    showToast("This labour requirement has already been added");
    return false;
  }
  const editIndex = activeTradeRequirementId
    ? pendingTradeRequirements.findIndex(
        (requirement) => requirement.id === activeTradeRequirementId,
      )
    : -1;
  const wasEditing = editIndex >= 0;
  if (wasEditing) {
    req.id = pendingTradeRequirements[editIndex].id;
    pendingTradeRequirements[editIndex] = req;
  } else {
    pendingTradeRequirements.push(req);
  }
  activeTradeRequirementId = "";
  clearTradeReqInputs();
  tradeRequirementEditorOpen = !jobWizardActive;
  setTradeRequirementMessage();
  syncTradeReqBuilderState();
  showToast(wasEditing ? "Labour requirement updated" : "Labour requirement saved");
  return true;
}

function renderTradeReqCards() {
  const list = document.getElementById("jobTradeReqList");
  if (!list) return;
  list.innerHTML = pendingTradeRequirements
    .map((r, i) => {
      const advanced = [
        accommodationSummaryFor(r),
      ].filter(Boolean);
      const quantity = Math.max(1, Number(r.quantity) || 1);
      return `
    <article class="jw-req-card">
      <div class="jw-req-main">
        <div class="jw-req-heading">
          <div>
            <div class="jw-req-trade">${escapeHtml(r.trade || "Labour requirement")}</div>
            ${r.specialism ? `<div class="jw-req-role">${escapeHtml(r.specialism)}</div>` : ""}
          </div>
        </div>
        ${r.grade || r.workActivity ? `<div class="jw-req-meta">${[r.grade, r.workActivity].filter(Boolean).map(escapeHtml).join(" · ")}</div>` : ""}
        ${credentialLabelsForRequirement(r).length ? `<div class="jw-req-quals"><span>Cards, tickets & qualifications</span>${escapeHtml(credentialLabelsForRequirement(r).join(" · "))}</div>` : ""}
        <div class="jw-req-summary">
          ${r.budgetMax ? `<span class="jw-req-rate">${formatMoney(r.budgetMax)}/day</span>` : ""}
          <span>${r.workerReceivesFullAdvertisedRate !== false ? "Full advertised rate" : "Service fee within advertised rate"}</span>
        </div>
        ${advanced.length ? `<div class="jw-req-conditions">${advanced.map((item) => `<span>${escapeHtml(item)}</span>`).join("")}</div>` : ""}
      </div>
      <strong class="jw-req-count">${quantity} worker${quantity === 1 ? "" : "s"}</strong>
      <div class="jw-req-actions">
        <button type="button" class="jw-req-action" data-req-edit="${i}">Edit</button>
        <button type="button" class="jw-req-action jw-req-action--danger" data-req-remove="${i}">Remove</button>
      </div>
    </article>`;
    })
    .join("");
}

function syncTradeReqBuilderState() {
  // While saved requirement cards exist the builder inputs may sit empty,
  // so relax native validation on them; it is restored when the list empties.
  const hasCards = pendingTradeRequirements.length > 0;
  ["jobTrade", "jobSpecialism", "workActivity", "jobQuantity", "jobBudgetMax"].forEach(
    (id) => {
      const el = document.getElementById(id);
      if (el) el.required = !hasCards;
    },
  );
  renderTradeReqCards();
  renderJobPricingBreakdown();
  updateTradeRequirementEditorState();
  syncJobLabourDisclosureState();
  renderJobPreferredWorkerChoices(getSessionUser());
  if (jobWizardActive && jobWizardStep === 2) renderJobWizardChrome();
}

function resetJobTradeRequirements() {
  pendingTradeRequirements = [];
  selectedJobCredentialIds = [];
  jobRequestedWorkerIds = [];
  specificWorkerPickerDraftIds = new Set();
  activeTradeRequirementId = "";
  tradeRequirementEditorOpen = !jobWizardActive;
  clearTradeReqInputs();
  setTradeRequirementMessage();
  syncTradeReqBuilderState();
}

document.getElementById("jobAddTradeBtn")?.addEventListener("click", () => {
  saveTradeRequirement();
});

document.getElementById("jobAddFirstRequirement")?.addEventListener("click", () => {
  openTradeRequirementEditor();
});

document.getElementById("jobAddAnotherRequirement")?.addEventListener("click", () => {
  openTradeRequirementEditor();
});

document.getElementById("jobDiscardTradeRequirement")?.addEventListener("click", () => {
  discardTradeRequirementEditorChanges();
});

document.getElementById("jobTradeReqList")?.addEventListener("click", (event) => {
  const editButton = event.target.closest("[data-req-edit]");
  if (editButton) {
    const requirement = pendingTradeRequirements[Number(editButton.dataset.reqEdit)];
    if (requirement) openTradeRequirementEditor(requirement);
    return;
  }
  const removeButton = event.target.closest("[data-req-remove]");
  if (!removeButton) return;
  const index = Number(removeButton.dataset.reqRemove);
  const removed = pendingTradeRequirements[index];
  pendingTradeRequirements.splice(index, 1);
  if (removed?.id === activeTradeRequirementId) {
    activeTradeRequirementId = "";
    clearTradeReqInputs();
  }
  if (!pendingTradeRequirements.length) tradeRequirementEditorOpen = !jobWizardActive;
  syncTradeReqBuilderState();
});

["input", "change"].forEach((eventName) => {
  document.getElementById("jobRequirementEditor")?.addEventListener(eventName, () => {
    setTradeRequirementMessage();
    updateTradeRequirementEditorState();
  });
});

[
  "jobBudgetMax",
  "jobAccommodationAllowance",
  "jobTrade",
  "jobSpecialism",
  "workActivity",
  "jobQuantity",
  "jobCredentialSearch",
  "jobWorkerReceivesFullRate",
].forEach((id) => {
  document.getElementById(id)?.addEventListener("input", renderJobPricingBreakdown);
  document.getElementById(id)?.addEventListener("change", renderJobPricingBreakdown);
});
renderJobPricingBreakdown();

// Restore the first saved requirement into the builder inputs when the form
// submits with incomplete builder fields (their `required` is relaxed while
// cards exist, so native validation passes). This listener is registered
// before the main submit handler, so the restored values are what it reads.
// It runs on the submit event itself, covering button clicks, Enter-key and
// programmatic submits alike.
function restoreFirstTradeRequirement() {
  if (!pendingTradeRequirements.length) return;
  const current = readTradeReqInputs();
  const incomplete =
    !current.trade ||
    !current.specialism ||
    !current.workActivity ||
    !current.requiredCredentialIds.length ||
    !current.budgetMax;
  if (incomplete) applyTradeReqToInputs(pendingTradeRequirements[0]);
}
jobForm?.addEventListener("submit", restoreFirstTradeRequirement);

document.querySelectorAll(".filter-chip").forEach((chip) => {
  chip.addEventListener("click", () => {
    document
      .querySelectorAll(".filter-chip")
      .forEach((c) => c.classList.remove("active"));
    chip.classList.add("active");
    activeFilter = chip.dataset.filter;
    renderWorkers();
  });
});

// ─── Session User Helper ──────────────────────────────────
function getSessionUser() {
  try {
    return JSON.parse(localStorage.getItem("onsite_auth_v1"));
  } catch (_) {
    return null;
  }
}

// ─── Tab Routing ──────────────────────────────────────────
function switchTab(tab, { scroll = true } = {}) {
  closeAppPopovers();
  document
    .querySelectorAll("[data-tab]")
    .forEach((btn) => btn.classList.toggle("active", btn.dataset.tab === tab));
  document
    .querySelectorAll(".tab-panel")
    .forEach((panel) =>
      panel.classList.toggle("active", panel.id === `tab-${tab}`),
    );
  if (scroll) scrollAppToTop();
}

function bindTabEvents() {
  document.querySelectorAll("[data-tab]").forEach((btn) => {
    btn.addEventListener("click", () => {
      clearCompanyKpiDrilldownForNavigation(btn.dataset.tab || "");
      if (btn.dataset.tab === "request-labour") {
        openLabourRequestPage();
        return;
      }
      if (btn.dataset.tab === "dashboard") activeCompanyProjectId = "";
      if (btn.dataset.tab === "attendance") {
        navigateToAttendanceList({ replace: true, scroll: false });
        switchTab("attendance");
        return;
      }
      if (window.location.hash.startsWith("#attendance/project/")) {
        activeAttendanceProjectId = "";
        history.replaceState({}, "", `${window.location.pathname}${window.location.search}`);
      }
      if (btn.dataset.tab === "jobs") {
        navigateToCompanyProjectsDirectory();
        return;
      }
      switchTab(btn.dataset.tab);
      if (btn.dataset.tab === "dashboard") render();
    });
  });
}
bindTabEvents();

document.addEventListener("click", (event) => {
  const btn = event.target.closest("[data-empty-tab]");
  if (!btn) return;
  const tab = btn.dataset.emptyTab;
  if (!tab) return;
  clearCompanyKpiDrilldownForNavigation(tab);
  if (tab === "request-labour") {
    openLabourRequestPage();
    return;
  }
  switchTab(tab);
  if (tab === "dashboard") render();
});

window.addEventListener("hashchange", () => {
  if (syncCompanyKpiDrilldownFromHash()) return;
  if (window.location.hash.startsWith("#attendance/project/")) {
    syncAttendanceProjectFromHash();
    switchTab("attendance");
    renderAttendance();
  } else if (activeAttendanceProjectId) {
    activeAttendanceProjectId = "";
    renderAttendance();
    scrollAppToTop();
  }
});

window.addEventListener("popstate", () => {
  if (syncCompanyKpiDrilldownFromHash()) return;
  if (window.location.hash.startsWith("#attendance/project/")) {
    syncAttendanceProjectFromHash();
    switchTab("attendance");
  } else if (activeAttendanceProjectId) {
    activeAttendanceProjectId = "";
  }
  renderAttendance();
  scrollAppToTop();
});

// ─── Nav Rebuild ──────────────────────────────────────────
const ORIG_TOP_NAV = document.querySelector(".tab-nav").innerHTML;
const ORIG_BOTTOM_NAV = document.querySelector(".bottom-nav").innerHTML;
const ORIG_DASHBOARD = document.getElementById("tab-dashboard").innerHTML;

const NAV_SM = {
  home: onsiteIcon("home", 16),
  jobs: onsiteIcon("briefcase", 16),
  bookings: onsiteIcon("calendar", 16),
  profile: onsiteIcon("user", 16),
  requests: onsiteIcon("fileText", 16),
  workforce: onsiteIcon("users", 16),
  account: onsiteIcon("user", 16),
  offers: onsiteIcon("tag", 16),
  notifications: onsiteIcon("bell", 16),
  market: onsiteIcon("users", 16),
};

const NAV_LG = Object.fromEntries(
  Object.entries(NAV_SM).map(([k, v]) => [
    k,
    v.replace(/width="16" height="16"/g, 'width="22" height="22"'),
  ]),
);

const WORKER_TABS = [
  { id: "dashboard", icon: "home", label: "Home" },
  { id: "offers", icon: "offers", label: "Offers" },
  { id: "calendar", icon: "bookings", label: "Calendar" },
  { id: "attendance", icon: "bookings", label: "Timesheet" },
  { id: "profile", icon: "profile", label: "Profile" },
];

const CONTRACTOR_TABS = [
  { id: "dashboard", icon: "home", label: "Dashboard" },
  { id: "jobs", icon: "jobs", label: "Projects" },
  { id: "request-labour", icon: "requests", label: "Request Labour" },
  { id: "attendance", icon: "bookings", label: "Attendance" },
  { id: "market", icon: "market", label: "Labour Insights" },
  { id: "notifications", icon: "notifications", label: "Notifications" },
];

function companyUnreadNotificationCount(user = getSessionUser()) {
  return companyVisibleNotifications(user).filter((n) => !n.readAt).length;
}

function updateCompanyNotificationBadges(user = getSessionUser()) {
  if (user?.type !== "company") return;
  const count = companyUnreadNotificationCount(user);
  document.querySelectorAll('[data-tab="notifications"]').forEach((btn) => {
    btn.querySelector(".nav-unread-badge")?.remove();
    if (!count) return;
    btn.insertAdjacentHTML("beforeend", `<span class="nav-unread-badge">${count}</span>`);
  });
}

function rebuildNav(tabDefs, activeId) {
  const topNav = document.querySelector(".tab-nav");
  const bottomNav = document.querySelector(".bottom-nav");
  if (!topNav || !bottomNav) return;
  const unreadCount = getSessionUser()?.type === "company" ? companyUnreadNotificationCount() : 0;
  topNav.innerHTML = tabDefs
    .map(
      (t) => `
    <button class="tab-btn${t.id === activeId ? " active" : ""}" data-tab="${t.id}" type="button">
      ${NAV_SM[t.icon] || ""}<span>${t.label}</span>${t.id === "notifications" && unreadCount ? `<span class="nav-unread-badge">${unreadCount}</span>` : ""}
    </button>`,
  )
    .join("") + `<div id="sidebarAccountSlot" class="sidebar-account-slot"></div>`;
  bottomNav.innerHTML = tabDefs
    .map(
      (t) => `
    <button class="bottom-nav-btn${t.id === activeId ? " active" : ""}" data-tab="${t.id}" type="button">
      ${NAV_LG[t.icon] || ""}
      <span>${t.label}</span>${t.id === "notifications" && unreadCount ? `<span class="nav-unread-badge">${unreadCount}</span>` : ""}
    </button>`,
    )
    .join("");
  bindTabEvents();
  renderSidebarAccount(getSessionUser());
}

function restoreNav() {
  document.querySelector(".tab-nav").innerHTML = ORIG_TOP_NAV;
  document.querySelector(".bottom-nav").innerHTML = ORIG_BOTTOM_NAV;
  bindTabEvents();
}

function companySidebarName(user) {
  return (
    user?.companyName ||
    user?.tradingName ||
    user?.registeredCompanyName ||
    user?.name ||
    "Company"
  );
}

function companySidebarInitials(name) {
  return String(name || "C")
    .trim()
    .split(/\s+/)
    .slice(0, 1)
    .map((word) => word[0]?.toUpperCase() || "")
    .join("") || "C";
}

function companySidebarUserRole(user) {
  const rawRole =
    user?.permissionRole ||
    user?.companyRole ||
    user?.userRole ||
    user?.role ||
    "administrator";
  const normalized = String(rawRole).trim().toLowerCase();
  const labels = {
    administrator: "Administrator",
    admin: "Administrator",
    manager: "Manager",
    supervisor: "Supervisor",
  };
  return labels[normalized] || rawRole;
}

function renderSidebarAccount(user) {
  const slot = document.getElementById("sidebarAccountSlot");
  if (!slot) return;
  if (user?.type !== "company") {
    slot.innerHTML = "";
    return;
  }
  const companyName = companySidebarName(user);
  const userName = user?.name || user?.fullName || "User";
  const userRole = companySidebarUserRole(user);
  slot.innerHTML = `
    <button class="sidebar-account-card" type="button" aria-expanded="false" data-sidebar-account-toggle>
      <span class="sidebar-company-avatar">${escapeHtml(companySidebarInitials(companyName))}</span>
      <span class="sidebar-company-text">
        <span class="sidebar-company-name">${escapeHtml(companyName)}</span>
        <span class="sidebar-user-name">${escapeHtml(userName)}</span>
        <span class="sidebar-user-role">${escapeHtml(userRole)}</span>
      </span>
      <span class="sidebar-account-chevron" aria-hidden="true">⌄</span>
    </button>
    <div class="sidebar-account-menu hidden" data-sidebar-account-menu>
      <button type="button" data-sidebar-account-action="profile">My Profile</button>
      <button type="button" data-sidebar-account-action="settings">Company Settings</button>
      <button type="button" data-sidebar-account-action="signout">Sign Out</button>
    </div>`;
  bindSidebarAccountMenu(slot);
}

function bindSidebarAccountMenu(slot) {
  const toggle = slot.querySelector("[data-sidebar-account-toggle]");
  const menu = slot.querySelector("[data-sidebar-account-menu]");
  if (!toggle || !menu) return;
  toggle.addEventListener("click", (event) => {
    event.stopPropagation();
    const isOpen = !menu.classList.contains("hidden");
    closeAppPopovers(toggle);
    menu.classList.toggle("hidden", isOpen);
    toggle.setAttribute("aria-expanded", String(!isOpen));
  });
  menu.querySelectorAll("[data-sidebar-account-action]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.stopPropagation();
      const action = btn.dataset.sidebarAccountAction;
      menu.classList.add("hidden");
      toggle.setAttribute("aria-expanded", "false");
      if (action === "signout") {
        if (typeof logoutCurrentUser === "function") logoutCurrentUser();
        return;
      }
      activeCompanyAccountView = action === "settings" ? "company" : "profile";
      switchTab("account");
      renderContractorAccount(getSessionUser());
    });
  });
}

document.addEventListener("click", (event) => {
  const slot = document.getElementById("sidebarAccountSlot");
  if (!slot || slot.contains(event.target)) return;
  slot.querySelector("[data-sidebar-account-menu]")?.classList.add("hidden");
  slot
    .querySelector("[data-sidebar-account-toggle]")
    ?.setAttribute("aria-expanded", "false");
});

// ─── Role-Based View ─────────────────────────────────────
function applyRoleView(user) {
  const role = user?.type || null;

  if (role === "worker") {
    rebuildNav(WORKER_TABS, "dashboard");
    // Update jobs panel header for workers
    const jobsHeader = document.querySelector("#tab-jobs .panel-title");
    const jobsSub = document.querySelector("#tab-jobs .panel-subtitle");
    const jobsPanelHeader = document.querySelector("#tab-jobs > .panel-header");
    if (jobsPanelHeader) jobsPanelHeader.style.display = "";
    if (jobsHeader) jobsHeader.textContent = "Available Jobs";
    if (jobsSub) jobsSub.textContent = "Open positions matching your trade";
    render();
    switchTab("dashboard");
  } else if (role === "company") {
    rebuildNav(CONTRACTOR_TABS, "dashboard");
    // Companies: show job form only, hide worker form and toggle bar
    document.querySelector(".add-toggle")?.classList.add("hidden");
    document.querySelector("#formWorker")?.classList.add("hidden");
    document.querySelector("#formJob")?.classList.add("hidden");
    // Update the add tab header for companies
    const addTitle = document.querySelector("#tab-add .form-card-header h3");
    const addSub = document.querySelector("#tab-add .form-card-header p");
    if (addTitle) addTitle.textContent = "Labour Request";
    if (addSub) addSub.textContent = "Post a new labour requirement";
    render();
    if (!syncCompanyKpiDrilldownFromHash({ scroll: false })) {
      switchTab("dashboard");
    }
  } else {
    // Admin / demo — restore original nav and dashboard
    restoreNav();
    document.getElementById("tab-dashboard").innerHTML = ORIG_DASHBOARD;
    const jobsHeader = document.querySelector("#tab-jobs .panel-title");
    const jobsSub = document.querySelector("#tab-jobs .panel-subtitle");
    const jobsPanelHeader = document.querySelector("#tab-jobs > .panel-header");
    if (jobsPanelHeader) jobsPanelHeader.style.display = "";
    if (jobsHeader) jobsHeader.textContent = "Job Requests";
    if (jobsSub) jobsSub.textContent = "Company requests awaiting assignment";
    render();
    switchTab("dashboard");
  }
}

// ─── Worker Home ──────────────────────────────────────────
function renderWorkerHome(user) {
  const el = document.getElementById("tab-dashboard");
  if (!el) return;

  const stats = getWorkerStats(user.id || "");
  const rating = buildWorkerRating(user.id || "");
  const reliability =
    rating.reliabilityScore != null
      ? rating.reliabilityScore
      : stats.totalShifts > 0
      ? (stats.reliability ?? 100)
      : (user.reliability ?? 100);
  const pct = calcWorkerCompletion(user);

  // Active booking
  const booking = state.jobs.find((j) => j.assignedWorkerId === user.id);

  // Recommended jobs (trade-matched, up to 3)
  const trade = canonicalTrade(user.trade);
  const recommended = [...state.jobs]
    .filter((j) => !trade || canonicalTrade(j.trade) === trade)
    .sort((a, b) => new Date(a.start || 0) - new Date(b.start || 0))
    .slice(0, 3);

  // Greeting
  const hr = new Date().getHours();
  const greet =
    hr < 12 ? "Good morning" : hr < 17 ? "Good afternoon" : "Good evening";

  // Days worked this month
  const thisMonth = new Date().toISOString().slice(0, 7);
  const daysThisMonth = attendanceRecords.filter(
    (r) =>
      r.workerId === user.id &&
      r.date.startsWith(thisMonth) &&
      (r.status === "onTime" || r.status === "late"),
  ).length;

  const bookingDayRate = booking
    ? booking.agreedDayRate != null
      ? booking.agreedDayRate
      : parseDayRate(booking.payRate)
    : 0;
  const bookingAgr = booking ? agreementForJob(booking) : null;
  const agrState = bookingAgr ? agreementWorkerState(bookingAgr) : "none";
  const bookingLive = booking ? bookingAgreementActive(booking) : false;
  const currentWorkerNotice = booking
    ? latestWorkerNoticeForJob(booking.id, user.id)
    : null;
  const currentWorkerRelease = booking
    ? latestReleaseForJob(booking.id, user.id)
    : null;
  const agreementBanner =
    booking && bookingAgr && agrState !== "active"
      ? `
    <div class="wh-agr-banner wh-agr-banner--${agrState === "pending_worker" ? "action" : "wait"}">
      <div class="wh-agr-banner-text">
        <strong>${agrState === "pending_worker" ? "Job Agreement — action needed" : "Job Agreement signed"}</strong>
        <span>${
          agrState === "pending_worker"
            ? "Review and accept your agreement to activate this booking. You can't check in or navigate to site until it's active."
            : "Waiting for the company to confirm. Your booking activates once they sign."
        }</span>
      </div>
      <button class="wh-agr-review-btn" type="button" data-agr-open="${bookingAgr.id}">${agrState === "pending_worker" ? "Review & Sign" : "View"}</button>
    </div>`
              : "";
  const isUnavailable = user.availability === "not available";
  const nextAvailable = formatDateInput(user.nextAvailableDate);
  const workerProfile = findWorker(user.id) || ensureWorkerProfileForUser(user);
  const workerOffers = (state.applications || []).filter(
    (a) =>
      a.workerId === user.id &&
      ["offered", "under_company_review", "confirmed", "declined_by_worker", "expired"].includes(
        a.status,
      ),
  );
  const activeOffers = workerOffers.filter((a) => a.status === "offered");
  const recentOfferHistory = workerOffers
    .filter((a) => a.status !== "offered")
    .slice(-3)
    .reverse();
  const workerHomeNotices = (workerProfile?.offerNotifications || []).filter(
    (n) => ["missed_2_offers", "assignment_release"].includes(n.type) && !n.readAt,
  );
  const pendingShiftChangeOffers = (state.shiftChangeOffers || []).filter(
    (offer) => offer.workerId === user.id && offer.status === "offered",
  );
  const plannedAbsences = plannedAbsencesForWorker(workerProfile || user);
  const preStartPanel = booking ? workerPreStartPanelHTML(booking, user.id) : "";
  const plannedAbsencePanel = `
    <div class="wh-section-label">Planned Absence</div>
    <div class="wh-planned-panel">
      <div class="wh-planned-form">
        <input id="whAbsenceEditId" type="hidden" value="" />
        <label class="wh-next-date">
          <span>Start Date</span>
          <input id="whAbsenceStart" type="date" />
        </label>
        <label class="wh-next-date">
          <span>End Date</span>
          <input id="whAbsenceEnd" type="date" />
        </label>
        <button class="wh-next-save" id="whAbsenceSave" type="button">Add</button>
        <button class="wh-planned-cancel hidden" id="whAbsenceCancel" type="button">Cancel</button>
      </div>
      <div class="wh-planned-warning hidden" id="whAbsenceWarning">
        This planned absence is inside the 5 working day notice period. Please inform your site supervisor directly as soon as possible.
      </div>
      ${
        plannedAbsences.length
          ? `<div class="wh-planned-list">
              ${plannedAbsences
                .map(
                  (absence) => `
                <div class="wh-planned-row">
                  <div>
                    <span>${formatDateOnly(absence.startDate)}</span>
                    <strong>${absence.endDate !== absence.startDate ? `to ${formatDateOnly(absence.endDate)}` : "Unavailable"}</strong>
                    ${plannedAbsenceNoticeMessage(absence) ? `<small>${escapeHtml(plannedAbsenceNoticeMessage(absence))}</small>` : ""}
                  </div>
                  <div class="wh-planned-actions">
                    <button type="button" data-absence-edit="${absence.id}">Edit</button>
                    <button type="button" data-absence-remove="${absence.id}">Remove</button>
                  </div>
                </div>`,
                )
                .join("")}
            </div>`
          : guidedEmptyStateHTML({
              kicker: "Planned Absence",
              title: "No planned absence added",
              body: "Add single dates or date ranges here when you know you will be unavailable for project work.",
            })
      }
    </div>`;
  const availabilityPanel = `
    <div class="wh-availability-panel">
      <div class="wh-availability-main">
        <button class="wh-avail-btn ${isUnavailable ? "unavailable" : "available"}"
          id="whAvailBtn" type="button">
          <span class="wh-avail-dot"></span>
          ${isUnavailable ? "Unavailable" : "Available"}
        </button>
        <label class="wh-next-date">
          <span>Next Available Date</span>
          <input id="whNextAvailableDate" type="date" value="${escapeHtml(nextAvailable)}" />
        </label>
        <button class="wh-next-save" id="whNextAvailableSave" type="button">Save</button>
      </div>
      ${
        isUnavailable
          ? `<div class="wh-unavailable-note">You’re currently unavailable. Toggle to available when you’re ready to start receiving job offers.</div>`
          : ""
      }
    </div>`;
  const missedNoticeHtml = workerHomeNotices.length
    ? workerHomeNotices
        .map(
          (n) => `<div class="wh-offer-notice">${escapeHtml(n.message)}${
            n.type === "missed_2_offers"
              ? " Consider setting a Next Available Date so contractors know when to offer you work again."
              : ""
          }</div>`,
        )
        .join("")
    : "";
  const offerCardHtml = (app) => {
    const job = applicationJob(app);
    const pay = job ? workerPayDisplay(job, workerProfile || user) : null;
    if (!job) return "";
    return `
      <div class="wh-offer-card">
        <div class="wh-offer-head">
          <span class="wh-offer-label">Job Offer</span>
          <span class="wh-offer-expiry">${escapeHtml(offerExpiryLabel(app))}</span>
        </div>
        <div class="wh-offer-title">${escapeHtml(job.trade)} · ${escapeHtml(job.location)}</div>
        <div class="wh-offer-meta">
          ${job.start ? formatDate(job.start) : "Start date TBC"}
          ${job.duration ? ` · ${escapeHtml(job.duration)}` : ""}
          ${pay != null ? ` · ${formatMoney(pay)}/day guaranteed` : ""}
        </div>
        <div class="wh-offer-site">
          Working days: ${escapeHtml(workingDaysLabel(job))}
          ${weekendRequirementLabel(job) ? ` · ${escapeHtml(weekendRequirementLabel(job))}` : ""}
          ${weekendRatesLabel(job) ? ` · ${escapeHtml(weekendRatesLabel(job))}` : ""}
        </div>
        ${job.siteName || job.siteAddress ? `<div class="wh-offer-site">${escapeHtml(job.siteName || job.siteAddress)}</div>` : ""}
        <div class="wh-offer-actions">
          ${job.sitePin ? `<button class="secondary-btn" type="button" data-map-job="${job.id}">Site Details</button>` : ""}
          <button class="secondary-btn wh-offer-decline" type="button" data-worker-offer-decline="${app.id}">Decline</button>
          <button class="primary-btn wh-offer-accept" type="button" data-worker-offer-accept="${app.id}">Accept</button>
        </div>
      </div>`;
  };
  const offerHistoryHtml = recentOfferHistory.length
    ? `<div class="wh-offer-history">
        ${recentOfferHistory
          .map((app) => {
            const job = applicationJob(app);
            const reason =
              app.workerDeclineReason || app.companyDeclineReason
                ? ` · ${escapeHtml(app.workerDeclineReason || app.companyDeclineReason)}`
                : "";
            return `<div class="wh-offer-history-row">
              <span>${escapeHtml(job?.trade || "Job")} · ${escapeHtml(job?.location || "")}</span>
              <strong>${escapeHtml(offerStatusLabel(app.status))}${reason}</strong>
            </div>`;
          })
          .join("")}
      </div>`
    : "";
  const offersPanel =
    missedNoticeHtml || activeOffers.length || offerHistoryHtml
      ? `
    <div class="wh-section-label">Job Offers</div>
    <div class="wh-offers-panel">
      ${missedNoticeHtml}
      ${
        activeOffers.length
          ? activeOffers.map(offerCardHtml).join("")
          : guidedEmptyStateHTML({
              kicker: "Offers",
              title: "No active job offers",
              body: "New offers will appear here when a contractor invites you to review a role. Keep your availability and travel preferences up to date.",
              actionLabel: "Update Availability",
              actionTab: "calendar",
            })
      }
      ${offerHistoryHtml}
    </div>`
      : "";
  const shiftChangePanel = pendingShiftChangeOffers.length
    ? `
    <div class="wh-section-label">Shift Change Offers</div>
    <div class="wh-offers-panel">
      ${pendingShiftChangeOffers
        .map((offer) => {
          const job = findJob(offer.jobId);
          return `<div class="wh-offer-card">
            <div class="wh-offer-head">
              <span class="wh-offer-label">Shift Change Offer</span>
              <span class="wh-offer-expiry">Worker choice required</span>
            </div>
            <div class="wh-offer-title">${escapeHtml(job?.trade || "Assignment")} · ${escapeHtml(job?.location || "")}</div>
            <div class="wh-offer-meta">
              ${escapeHtml(offer.proposedShiftPattern || "Shift")} · ${escapeHtml(offer.proposedShiftStartTime)} to ${escapeHtml(offer.proposedShiftFinishTime)}
              ${offer.effectiveDate ? ` · from ${formatDateOnly(offer.effectiveDate)}` : ""}
              ${offer.revisedOfferedRate ? ` · ${formatMoney(Number(offer.revisedOfferedRate))}/day offered` : ""}
            </div>
            <div class="wh-offer-actions">
              <button class="secondary-btn wh-offer-decline" type="button" data-shift-change-decline="${offer.id}">Decline</button>
              <button class="primary-btn wh-offer-accept" type="button" data-shift-change-accept="${offer.id}">Accept</button>
            </div>
          </div>`;
        })
        .join("")}
    </div>`
    : "";
  const signInPanel =
    booking && bookingLive
      ? `
    <div class="wh-signin-panel">
      <div class="wh-signin-copy">
        <div class="wh-section-label">Site Sign In</div>
        <div class="wh-signin-title">${escapeHtml(booking.trade)} · ${escapeHtml(booking.location)}</div>
        <div class="wh-signin-sub">Today ${escapeHtml(jobExpectedStartTime(booking))}${booking.shiftFinishTime ? ` to ${escapeHtml(booking.shiftFinishTime)}` : ""} · camera scanner-ready site QR.</div>
      </div>
      <div class="wh-signin-actions">
        <button class="wh-signin-btn" type="button" data-worker-home-signin="${user.id}">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg>
          Sign In
        </button>
        <button class="secondary-btn" type="button" data-worker-home-late="${user.id}">Report Running Late</button>
      </div>
    </div>`
      : "";
  const noAssignmentPanel =
    !booking
      ? `<div class="wh-booking-card worker-daily-empty">
          <div class="wh-booking-label">No current assignment</div>
          <div class="wh-booking-trade">You are ${isUnavailable ? "unavailable" : "available"} for job offers.</div>
          <div class="wh-booking-meta">${isUnavailable && nextAvailable ? `Next available ${formatDateOnly(nextAvailable)}` : "Keep your profile ready for new offers."}</div>
          <button class="secondary-btn wide" type="button" data-tab="calendar">${isUnavailable ? "Update Availability" : "View Calendar"}</button>
        </div>`
      : "";
  const outstandingPreStart = booking
    ? preStartRequirementSummary(booking, user.id).outstanding.length
    : 0;
  const homeNotifications = workerNotificationItems(user, workerProfile, booking);
  const notificationPanel = `
    <div class="worker-home-topbar">
      <button class="worker-bell-btn" type="button" data-worker-notifications>
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 7h18s-3 0-3-7"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg>
        <span>Notifications</span>
        <strong>${homeNotifications.length}</strong>
      </button>
    </div>
    <div class="worker-notification-panel hidden" id="workerNotificationPanel">
      ${
        homeNotifications.length
          ? homeNotifications.map((item) => `<div class="worker-notification-row"><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.body)}</span></div>`).join("")
          : guidedEmptyStateHTML({
              kicker: "Notifications",
              title: "No important notifications",
              body: "New offers, agreement reminders, planned absence updates and attendance alerts will appear here.",
            })
      }
    </div>`;
  const homeOffersPanel =
    activeOffers.length || pendingShiftChangeOffers.length
      ? `<div class="worker-daily-card">
          <div>
            <span class="worker-daily-kicker">Pending offers</span>
            <strong>${activeOffers.length + pendingShiftChangeOffers.length}</strong>
            <small>${activeOffers.length ? `${activeOffers.length} job offer${activeOffers.length === 1 ? "" : "s"}` : ""}${pendingShiftChangeOffers.length ? `${activeOffers.length ? " · " : ""}${pendingShiftChangeOffers.length} shift change` : ""}</small>
          </div>
          <button class="secondary-btn" type="button" data-tab="offers">Review</button>
        </div>`
      : "";
  const preStartSummaryPanel =
    outstandingPreStart > 0
      ? `<div class="worker-daily-card worker-daily-card--warn">
          <div>
            <span class="worker-daily-kicker">Pre-start documents</span>
            <strong>${outstandingPreStart} outstanding</strong>
            <small>Acknowledge required documents before you start.</small>
          </div>
          <button class="secondary-btn" type="button" data-tab="profile">View</button>
        </div>`
      : "";
  const mobileDailyPanel = booking
    ? dailyMobileJobsPanelHTML(booking, { workerView: true })
    : "";
  const activeBookingHtml = booking
    ? `
    <div class="wh-booking-card">
      <div class="wh-booking-head">
        <div class="wh-booking-label">${bookingLive ? "Active Booking" : "Booking — Pending Agreement"}</div>
        <span class="protected-badge">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
          Protected
        </span>
      </div>
      ${agreementBanner}
      <div class="wh-booking-trade">${escapeHtml(booking.trade)}</div>
      <div class="wh-booking-meta">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
        ${escapeHtml(booking.location)}
        ${booking.start ? ` · ${new Date(booking.start).toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" })}` : ""}
        ${booking.duration ? ` · ${escapeHtml(booking.duration)}` : ""}
        ${bookingDayRate ? ` · <strong>${formatMoney(bookingDayRate)}/day</strong>` : booking.payRate ? ` · <strong>${escapeHtml(booking.payRate)}</strong>` : ""}
      </div>
      ${booking.sitePin ? `<button class="site-loc-view-btn" type="button" data-map-job="${booking.id}">Site Details</button>` : ""}
      ${booking.estimatedEndDate || booking.endDate ? `<div class="wh-booking-end">Estimated end: <strong>${formatDate(booking.estimatedEndDate || booking.endDate)}</strong></div>` : ""}
      ${
        currentWorkerNotice
          ? `<div class="notice-status-panel"><strong>Notice logged:</strong> proposed last working day ${formatDateOnly(currentWorkerNotice.proposedLastWorkingDay)} · ${escapeHtml(currentWorkerNotice.reason)}</div>`
          : ""
      }
      ${
        currentWorkerRelease
          ? `<div class="notice-status-panel"><strong>${escapeHtml(releaseTypeLabel(currentWorkerRelease.releaseType))}:</strong> ${escapeHtml(releaseStatusLabel(currentWorkerRelease.releaseStatus))} · effective ${formatDateOnly(currentWorkerRelease.effectiveDate)}</div>`
          : ""
      }
      ${
        booking.extensionRequestedAt
          ? `
        <div class="wh-ext-request">
          <div class="wh-ext-req-title">Extension requested</div>
          <div class="wh-ext-req-body">${escapeHtml(booking.companyName || "Your company")} wants to extend your booking until <strong>${formatDate(booking.newProposedEndDate)}</strong> at <strong>${formatMoney(booking.proposedDayRate || bookingDayRate)}/day</strong>.</div>
          <div class="wh-ext-actions">
            <button class="wh-ext-btn wh-ext-accept" type="button" data-ext-accept="${booking.id}">Accept</button>
            <button class="wh-ext-btn wh-ext-decline" type="button" data-ext-decline="${booking.id}">Decline</button>
          </div>
        </div>`
          : booking.extensionJustExtended ||
              (booking.extensionStatus && booking.extensionStatus !== "pending")
            ? `
        <div class="wh-ext-note ${extensionStatusLabel(booking).cls}">${
          booking.extensionJustExtended
            ? "Extension confirmed — you're booked to the new end date."
            : booking.extensionStatus === "declined_by_worker"
              ? "You declined the extension. You'll be available for new projects from the end date."
              : "This booking is ending as planned. You'll be available for new projects from the end date."
        }</div>`
            : ""
      }
      <button class="secondary-btn wide" type="button" data-worker-notice="${booking.id}">Give Notice</button>
      <div class="wh-booking-protect">If your company cancels within ${PROTECTION_WINDOW_DAYS} working days of the start date, you're owed 1 day's pay${bookingDayRate ? ` (${formatMoney(bookingDayRate)})` : ""}.</div>
    </div>`
    : "";

  const recJobsHtml = recommended.length
    ? `
    <div class="wh-section-label">Recommended for You</div>
    ${recommended
      .map((job) => {
        const recPay = workerPayDisplay(job, user);
        const daysUntil = job.start
          ? Math.ceil((new Date(job.start) - new Date()) / 86400000)
          : null;
        const urgency =
          daysUntil !== null
            ? daysUntil <= 0
              ? `<span class="wjc-urgency urgency-now">Today</span>`
              : daysUntil === 1
                ? `<span class="wjc-urgency urgency-soon">Tomorrow</span>`
                : daysUntil <= 7
                  ? `<span class="wjc-urgency urgency-soon">${daysUntil}d</span>`
                  : `<span class="wjc-urgency urgency-later">${daysUntil}d</span>`
            : "";
        return `
      <div class="wh-rec-job" data-apply-home="${job.id}">
        <div class="wh-rec-left">
          <div class="wh-rec-trade">${escapeHtml(job.trade)}</div>
          <div class="wh-rec-loc">
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
            ${escapeHtml(job.location)}
            ${recPay != null ? ` · <strong>${formatMoney(recPay)}/day</strong>` : ""}
          </div>
        </div>
        <div class="wh-rec-right">${urgency}<svg class="wh-rec-arrow" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg></div>
      </div>`;
      })
      .join("")}
    <button class="wh-view-all" type="button" data-tab="jobs">View all jobs →</button>`
    : `
    <div class="wh-section-label">Recommended for You</div>
    ${guidedEmptyStateHTML({
      kicker: "Matching",
      title: "No recommended roles right now",
      body: `There are no open ${user.trade || "job"} roles matching your profile at the moment. Keep your availability, travel radius and documents up to date for future offers.`,
      actionLabel: "Update Profile",
      actionTab: "profile",
    })}`;

  el.innerHTML = `
    <div class="worker-home-head">
      <div class="wh-greeting">${greet}, <strong>${escapeHtml((user.name || "").split(" ")[0])}</strong></div>
      ${notificationPanel}
    </div>
    ${availabilityPanel}
    ${homeOffersPanel}
    ${preStartSummaryPanel}
    ${signInPanel}
    ${noAssignmentPanel}
    ${mobileDailyPanel}
    ${activeBookingHtml}
    ${preStartPanel}`;

  // Availability toggle
  document.getElementById("whAvailBtn")?.addEventListener("click", () => {
    const session = JSON.parse(
      localStorage.getItem("onsite_auth_v1") || "null",
    );
    if (!session) return;
    const nextAvailability =
      session.availability === "not available" ? "available" : "not available";
    if (nextAvailability === "available") {
      alert(
        "By marking yourself as available, you may receive job offers from contractors. If you are currently in work/unavailable, set yourself to unavailable until you are ready for a new assignment.",
      );
    } else if (confirm("Would you like to set your next available date?")) {
      setTimeout(() => {
        const nextDateInput = document.getElementById("whNextAvailableDate");
        nextDateInput?.scrollIntoView({ behavior: "smooth", block: "center" });
        nextDateInput?.focus();
      }, 0);
    }
    const nextDate = document.getElementById("whNextAvailableDate")?.value || "";
    updateWorkerAvailability(session.id, nextAvailability, nextDate);
    render();
    showToast(`Status set to ${nextAvailability}`);
  });

  document
    .getElementById("whNextAvailableSave")
    ?.addEventListener("click", () => {
      const session = JSON.parse(
        localStorage.getItem("onsite_auth_v1") || "null",
      );
      if (!session) return;
      const nextDate =
        document.getElementById("whNextAvailableDate")?.value || "";
      updateWorkerAvailability(
        session.id,
        session.availability || "available",
        nextDate,
      );
      render();
      showToast("Next available date saved");
    });

  document.getElementById("whAbsenceSave")?.addEventListener("click", () => {
    const editId = document.getElementById("whAbsenceEditId")?.value || "";
    const startDate = document.getElementById("whAbsenceStart")?.value || "";
    const endDate = document.getElementById("whAbsenceEnd")?.value || "";
    const res = upsertWorkerPlannedAbsence(user.id, editId, startDate, endDate);
    if (!res.ok) {
      showToast(res.reason);
      return;
    }
    const warning = plannedAbsenceNoticeMessage(res.absence);
    render();
    if (warning) alert(warning);
    showToast(editId ? "Planned Absence updated" : "Planned Absence added");
  });

  document.getElementById("whAbsenceCancel")?.addEventListener("click", () => {
    render();
  });

  const updateAbsenceWarning = () => {
    const startDate = document.getElementById("whAbsenceStart")?.value || "";
    document
      .getElementById("whAbsenceWarning")
      ?.classList.toggle("hidden", !plannedAbsenceInsideNotice(startDate));
  };
  document.getElementById("whAbsenceStart")?.addEventListener("change", updateAbsenceWarning);

  el.querySelectorAll("[data-absence-edit]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const absence = plannedAbsences.find((a) => a.id === btn.dataset.absenceEdit);
      if (!absence) return;
      const idInput = document.getElementById("whAbsenceEditId");
      const startInput = document.getElementById("whAbsenceStart");
      const endInput = document.getElementById("whAbsenceEnd");
      if (idInput) idInput.value = absence.id;
      if (startInput) startInput.value = absence.startDate;
      if (endInput) endInput.value = absence.endDate;
      const saveBtn = document.getElementById("whAbsenceSave");
      if (saveBtn) saveBtn.textContent = "Update";
      document.getElementById("whAbsenceCancel")?.classList.remove("hidden");
      updateAbsenceWarning();
    });
  });

  el.querySelectorAll("[data-absence-remove]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const res = removeWorkerPlannedAbsence(user.id, btn.dataset.absenceRemove);
      if (!res.ok) {
        showToast(res.reason);
        return;
      }
      render();
      showToast("Planned Absence removed");
    });
  });

  el.querySelectorAll("[data-worker-offer-accept]").forEach((btn) => {
    btn.addEventListener("click", () => workerAcceptOffer(btn.dataset.workerOfferAccept));
  });
  el.querySelectorAll("[data-worker-offer-decline]").forEach((btn) => {
    btn.addEventListener("click", () =>
      openOfferDecisionModal("worker", btn.dataset.workerOfferDecline),
    );
  });
  el.querySelectorAll("[data-shift-change-accept]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const res = respondToShiftChangeOffer(btn.dataset.shiftChangeAccept, true);
      if (!res.ok) {
        showToast(res.reason);
        return;
      }
      saveAndRender();
      showToast("Shift change accepted");
    });
  });
  el.querySelectorAll("[data-shift-change-decline]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const res = respondToShiftChangeOffer(btn.dataset.shiftChangeDecline, false);
      if (!res.ok) {
        showToast(res.reason);
        return;
      }
      saveAndRender();
      showToast("Shift change declined");
    });
  });
  el.querySelectorAll("[data-worker-home-signin]").forEach((btn) => {
    btn.addEventListener("click", () =>
      openWorkerQrScanner(btn.dataset.workerHomeSignin, workerProfile || user),
    );
  });
  el.querySelectorAll("[data-worker-home-late]").forEach((btn) => {
    btn.addEventListener("click", () => openReportModal(btn.dataset.workerHomeLate));
  });
  el.querySelector("[data-worker-notifications]")?.addEventListener("click", (event) => {
    event.stopPropagation();
    const panel = document.getElementById("workerNotificationPanel");
    const isOpen = !!panel && !panel.classList.contains("hidden");
    closeAppPopovers(event.currentTarget);
    panel?.classList.toggle("hidden", isOpen);
    event.currentTarget.setAttribute("aria-expanded", String(!isOpen));
  });
  el.querySelectorAll("[data-map-job]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.stopPropagation();
      openSiteMap(btn.dataset.mapJob);
    });
  });
  el.querySelectorAll("[data-worker-notice]").forEach((btn) => {
    btn.addEventListener("click", () => openWorkerNoticeModal(btn.dataset.workerNotice));
  });
  bindPreStartDocumentButtons(el, user.id);

  // Recommended job clicks → go to Jobs tab
  el.querySelectorAll("[data-apply-home]").forEach((row) => {
    row.addEventListener("click", () => switchTab("jobs"));
  });
  el.querySelectorAll("[data-tab]").forEach((btn) => {
    btn.addEventListener("click", () => switchTab(btn.dataset.tab));
  });
  bindAgreementOpeners(el);
  bindExtensionButtons(el);
}

function workerNotificationItems(user, workerProfile, booking) {
  const items = [];
  const activeOffers = (state.applications || []).filter(
    (app) => app.workerId === user.id && app.status === "offered",
  );
  activeOffers.forEach((app) => {
    const job = applicationJob(app);
    items.push({
      title: "New offer",
      body: `${job?.trade || "Job"} · ${job?.location || "Location TBC"} · ${offerExpiryLabel(app)}`,
    });
  });
  (state.applications || [])
    .filter(
      (app) =>
        app.workerId === user.id &&
        ["under_company_review", "confirmed", "declined_by_worker"].includes(app.status),
    )
    .slice(-3)
    .forEach((app) => {
      items.push({
        title: offerStatusLabel(app.status),
        body: `${app.trade || applicationJob(app)?.trade || "Offer"} · ${app.location || applicationJob(app)?.location || ""}`,
      });
    });
  (workerProfile?.offerNotifications || [])
    .filter((n) => !n.readAt)
    .forEach((n) => items.push({ title: "Notification", body: n.message || n.type }));
  if (booking) {
    const agr = agreementForJob(booking);
    if (agr && agreementWorkerState(agr) === "pending_worker") {
      items.push({
        title: "Agreement reminder",
        body: "Review and sign your Job Agreement before QR sign-in becomes active.",
      });
    }
    const preStart = preStartRequirementSummary(booking, user.id);
    if (preStart.outstanding.length) {
      items.push({
        title: "Document reminder",
        body: `${preStart.outstanding.length} pre-start document${preStart.outstanding.length === 1 ? "" : "s"} outstanding.`,
      });
    }
    const todayLate = attendanceRecords.find(
      (rec) => rec.workerId === user.id && rec.jobId === booking.id && rec.date === todayDateStr() && rec.lateReport,
    );
    if (todayLate?.lateReport?.supervisorDecision) {
      items.push({
        title: "Late report response",
        body: todayLate.lateReport.supervisorDecision.replaceAll("_", " "),
      });
    }
  }
  const expiringDocs = workerDocumentsFor(workerProfile || user).filter(
    (doc) => ["expired", "expiring"].includes(workerDocumentExpiryStatus(doc.expiryDate).cls),
  );
  if (expiringDocs.length) {
    items.push({
      title: "Document reminder",
      body: `${expiringDocs.length} document${expiringDocs.length === 1 ? "" : "s"} expired or expiring soon.`,
    });
  }
  return items;
}

function workerOfferDecisionCardHTML(app, user) {
  const job = applicationJob(app);
  const pay = job ? workerPayDisplay(job, user) : null;
  if (!job) return "";
  const active = app.status === "offered";
  return `
    <article class="worker-flow-card">
      <div class="worker-flow-card-head">
        <div>
          <span class="worker-daily-kicker">${active ? "Active offer" : "Offer history"}</span>
          <h3>${escapeHtml(job.trade || "Job")} · ${escapeHtml(job.location || "Location TBC")}</h3>
        </div>
        <strong>${escapeHtml(active ? offerExpiryLabel(app) : offerStatusLabel(app.status))}</strong>
      </div>
      <div class="worker-flow-meta">
        ${job.start ? formatDate(job.start) : "Start date TBC"}
        ${job.duration ? ` · ${escapeHtml(job.duration)}` : ""}
        ${pay != null ? ` · ${formatMoney(pay)}/day offered` : ""}
      </div>
      <div class="worker-flow-meta">Working days: ${escapeHtml(workingDaysLabel(job))}${weekendRatesLabel(job) ? ` · ${escapeHtml(weekendRatesLabel(job))}` : ""}</div>
      ${
        app.workerDeclineReason
          ? `<div class="worker-flow-note">Decline reason: ${escapeHtml(app.workerDeclineReason)}${app.workerDeclineComment ? ` · ${escapeHtml(app.workerDeclineComment)}` : ""}</div>`
          : ""
      }
      ${
        active
          ? `<div class="worker-flow-actions">
              ${job.sitePin ? `<button class="secondary-btn" type="button" data-map-job="${job.id}">Site Details</button>` : ""}
              <button class="secondary-btn" type="button" data-worker-offer-decline="${app.id}">Decline</button>
              <button class="primary-btn" type="button" data-worker-offer-accept="${app.id}">Accept</button>
            </div>`
          : ""
      }
    </article>`;
}

function renderWorkerOffersPage(user) {
  const el = document.getElementById("offersContent");
  if (!el) return;
  const apps = (state.applications || [])
    .filter((app) => app.workerId === user.id)
    .sort(
      (a, b) =>
        new Date(b.updatedAt || b.createdAt || 0) -
        new Date(a.updatedAt || a.createdAt || 0),
    );
  const active = apps.filter((app) => app.status === "offered");
  const history = apps.filter((app) => app.status !== "offered").slice(0, 10);
  const shiftChanges = (state.shiftChangeOffers || []).filter(
    (offer) => offer.workerId === user.id && offer.status === "offered",
  );
  const openJobs = workerOpenJobs(user).slice(0, 8);
  el.innerHTML = `
    <div class="worker-page">
      <section class="worker-page-section">
        <div class="worker-section-head">
          <h2>Active offers</h2>
          <span>${active.length}</span>
        </div>
        ${active.length ? active.map((app) => workerOfferDecisionCardHTML(app, user)).join("") : guidedEmptyStateHTML({
          kicker: "Offers",
          title: "No active offers",
          body: "You do not have any offers waiting for a response. Contractors can send offers when your availability, trade and travel preferences fit their project.",
          actionLabel: "Review Availability",
          actionTab: "calendar",
        })}
      </section>
      ${
        shiftChanges.length
          ? `<section class="worker-page-section">
              <div class="worker-section-head">
                <h2>Shift change offers</h2>
                <span>${shiftChanges.length}</span>
              </div>
              ${shiftChanges
                .map((offer) => {
                  const job = findJob(offer.jobId);
                  return `<article class="worker-flow-card">
                    <div class="worker-flow-card-head">
                      <div>
                        <span class="worker-daily-kicker">Shift change</span>
                        <h3>${escapeHtml(job?.trade || "Assignment")} · ${escapeHtml(job?.location || "")}</h3>
                      </div>
                      <strong>Decision needed</strong>
                    </div>
                    <div class="worker-flow-meta">${escapeHtml(offer.proposedShiftPattern || "Shift")} · ${escapeHtml(offer.proposedShiftStartTime)} to ${escapeHtml(offer.proposedShiftFinishTime)}${offer.effectiveDate ? ` · from ${formatDateOnly(offer.effectiveDate)}` : ""}</div>
                    <div class="worker-flow-actions">
                      <button class="secondary-btn" type="button" data-shift-change-decline="${offer.id}">Decline</button>
                      <button class="primary-btn" type="button" data-shift-change-accept="${offer.id}">Accept</button>
                    </div>
                  </article>`;
                })
                .join("")}
            </section>`
          : ""
      }
      <section class="worker-page-section">
        <div class="worker-section-head">
          <h2>Open opportunities</h2>
          <span>${openJobs.length}</span>
        </div>
        ${openJobs.length ? openJobs.map((job) => workerJobCard(job, user)).join("") : guidedEmptyStateHTML({
          kicker: "Matching",
          title: "No matching jobs right now",
          body: "There are no open roles matching your trade at the moment. Update your profile, travel radius and availability to improve future matching.",
          actionLabel: "Open Profile",
          actionTab: "profile",
        })}
      </section>
      <section class="worker-page-section">
        <div class="worker-section-head">
          <h2>Previous offers</h2>
          <span>${history.length}</span>
        </div>
        ${history.length ? history.map((app) => workerOfferDecisionCardHTML(app, user)).join("") : guidedEmptyStateHTML({
          kicker: "Offer History",
          title: "No previous offers yet",
          body: "Accepted, declined and expired offers will be kept here so you can track your work opportunities.",
        })}
      </section>
    </div>`;
  bindWorkerOfferButtons(el);
  bindWorkerJobBoardButtons(el, user);
}

function workerOpenJobs(user) {
  const trade = canonicalTrade(user?.trade);
  return [...state.jobs]
    .filter(
      (job) =>
        !job.assignedWorkerId &&
        !job.completed &&
        (!trade || canonicalTrade(job.trade) === trade),
    )
    .sort((a, b) => new Date(a.start || 0) - new Date(b.start || 0));
}

