function bindMobileDailyJobButtons(scope) {
  scope.querySelectorAll("[data-mobile-day-add]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const jobId = btn.dataset.mobileDayAdd;
      const res = upsertDailyJobEntry(jobId, {
        date: scope.querySelector(`[data-mobile-day-date="${jobId}"]`)?.value || "",
        clientSiteName:
          scope.querySelector(`[data-mobile-day-site="${jobId}"]`)?.value || "",
        siteAddress:
          scope.querySelector(`[data-mobile-day-address="${jobId}"]`)?.value || "",
        companyJobNumber:
          scope.querySelector(`[data-mobile-day-job-number="${jobId}"]`)?.value ||
          "",
        clientReference:
          scope.querySelector(`[data-mobile-day-client-ref="${jobId}"]`)?.value ||
          "",
        invoiceReference:
          scope.querySelector(`[data-mobile-day-invoice-ref="${jobId}"]`)?.value ||
          "",
        workNotes:
          scope.querySelector(`[data-mobile-day-notes="${jobId}"]`)?.value || "",
      });
      if (!res.ok) {
        showToast(res.reason);
        return;
      }
      saveAndRender();
      showToast("Daily mobile job added");
    });
  });
  scope.querySelectorAll("[data-mobile-day-remove]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const [jobId, dailyJobId] = btn.dataset.mobileDayRemove.split(":");
      const res = removeDailyJobEntry(jobId, dailyJobId);
      if (!res.ok) {
        showToast(res.reason);
        return;
      }
      saveAndRender();
      showToast("Daily mobile job removed");
    });
  });
}

function navigateToCompanyProjectsDirectory({ scroll = true } = {}) {
  activeCompanyProjectId = "";
  activeCompanyProjectEditId = "";
  activeCompanyProjectSection = "overview";
  activeCompanyProjectDocumentsView = "requirements";
  resetProjectEditMap();
  if (getSessionUser()?.type === "company") switchTab("jobs", { scroll: false });
  render();
  if (scroll) scrollAppToTop();
}

function bindCompanyProjectDashboardButtons(scope) {
  const openCompanyProject = (jobId) => {
    activeCompanyProjectId = jobId || "";
    activeCompanyProjectEditId = "";
    resetProjectEditMap();
    activeCompanyProjectSection = "overview";
    activeCompanyProjectDocumentsView = "requirements";
    if (getSessionUser()?.type === "company") switchTab("jobs", { scroll: false });
    render();
    scrollAppToTop();
  };
  scope.querySelectorAll("[data-dashboard-kpi]").forEach((btn) => {
    btn.addEventListener("click", () => {
      navigateToCompanyKpiDrilldown(btn.dataset.dashboardKpi || "");
    });
  });
  scope.querySelectorAll("[data-project-health-popover]").forEach((el) => {
    el.addEventListener("click", (event) => event.stopPropagation());
    el.addEventListener("keydown", (event) => {
      if (event.key !== "Escape") event.stopPropagation();
    });
  });
  scope
    .querySelectorAll("[data-company-project-open], [data-company-project-card]")
    .forEach((btn) => {
    btn.addEventListener("click", (event) => {
      if (
        btn.hasAttribute("data-company-project-card") &&
        event.target.closest("button, a, input, select, textarea, summary, details")
      ) {
        return;
      }
      event.stopPropagation();
      openCompanyProject(
        btn.dataset.companyProjectOpen || btn.dataset.companyProjectCard || "",
      );
    });
    btn.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      if (
        btn.hasAttribute("data-company-project-card") &&
        event.target !== btn
      ) {
        return;
      }
      event.preventDefault();
      event.stopPropagation();
      openCompanyProject(
        btn.dataset.companyProjectOpen || btn.dataset.companyProjectCard || "",
      );
    });
  });
  scope.querySelectorAll("[data-company-project-open-section]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.stopPropagation();
      activeCompanyProjectId = btn.dataset.companyProjectOpenSection || "";
      activeCompanyProjectEditId = "";
      activeCompanyProjectSection = normalizeCompanyProjectSection(btn.dataset.companySectionTarget || "overview");
      activeCompanyProjectDocumentsView = "requirements";
      resetProjectEditMap();
      if (getSessionUser()?.type === "company") switchTab("jobs", { scroll: false });
      render();
      scrollAppToTop();
    });
  });
  scope.querySelectorAll("[data-dashboard-attendance-project]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.stopPropagation();
      switchTab("attendance");
      navigateToAttendanceProject(btn.dataset.dashboardAttendanceProject || "");
      render();
      scrollAppToTop();
    });
  });
  scope.querySelectorAll("[data-company-project-close]").forEach((btn) => {
    btn.addEventListener("click", () => {
      navigateToCompanyProjectsDirectory();
    });
  });
  scope.querySelectorAll("[data-company-project-retry]").forEach((btn) => {
    btn.addEventListener("click", () => {
      render();
      scrollAppToTop();
    });
  });
  scope.querySelectorAll("[data-project-request-more]").forEach((btn) => {
    btn.addEventListener("click", () => {
      openLabourRequestWorkflow();
      const job = findJob(btn.dataset.projectRequestMore);
      if (job) showToast(`Use this request as the reference for ${job.projectName || job.trade}`);
    });
  });
  scope.querySelectorAll("[data-repeat-project]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.stopPropagation();
      repeatProject(btn.dataset.repeatProject || "");
    });
  });
  scope.querySelectorAll("[data-project-attendance]").forEach((btn) => {
    btn.addEventListener("click", () => switchTab("attendance"));
  });
  scope.querySelectorAll("[data-worker-calendar]").forEach((btn) => {
    btn.addEventListener("click", () =>
      openWorkerPlannedAbsenceCalendar(btn.dataset.workerCalendar),
    );
  });
  scope.querySelectorAll("[data-map-job]").forEach((btn) => {
    btn.addEventListener("click", () => openSiteMap(btn.dataset.mapJob));
  });
  scope.querySelectorAll("[data-project-qr-print]").forEach((btn) => {
    btn.addEventListener("click", () =>
      openProjectSignInPrintSheet(btn.dataset.projectQrPrint),
    );
  });
  scope.querySelectorAll("[data-project-qr-regenerate]").forEach((btn) => {
    btn.addEventListener("click", () =>
      openQrRegenerationConfirm(btn.dataset.projectQrRegenerate),
    );
  });
  scope.querySelectorAll("[data-company-project-section]").forEach((btn) => {
    btn.addEventListener("click", () => {
      activeCompanyProjectSection = normalizeCompanyProjectSection(btn.dataset.companyProjectSection || "overview");
      render();
      scrollAppToTop();
    });
  });
  scope.querySelectorAll("[data-company-worker-profile]").forEach((btn) => {
    btn.addEventListener("click", () =>
      openCompanyWorkerProfileModal(
        btn.dataset.companyWorkerProfile,
        btn.dataset.companyWorkerJob,
      ),
    );
  });
  bindProjectEditControls(scope);
}

function bindCompanyProjectSearch(scope) {
  scope
    .querySelectorAll("#companyDashboardProjectSearch, #companyProjectsSearch")
    .forEach((input) => {
      input.addEventListener("input", () => {
        const inputId = input.id;
        const cursor = input.selectionStart || input.value.length;
        const applySearch = () => {
          activeCompanyProjectSearch = input.value || "";
          render();
          requestAnimationFrame(() => {
            const nextInput = document.getElementById(inputId);
            if (!nextInput) return;
            nextInput.focus();
            nextInput.setSelectionRange(cursor, cursor);
          });
        };
        if (inputId !== "companyProjectsSearch") {
          applySearch();
          return;
        }
        window.clearTimeout(companyProjectSearchTimer);
        companyProjectSearchTimer = window.setTimeout(applySearch, 140);
      });
    });
  scope.querySelectorAll("[data-company-sort-option]").forEach((btn) => {
    btn.addEventListener("click", () => {
      activeCompanyProjectSort = btn.dataset.companySortOption || "health_priority";
      closeAppPopovers();
      render();
    });
  });
  scope.querySelectorAll("[data-company-operational-filter]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const filter = btn.dataset.companyOperationalFilter || "";
      closeAppPopovers();
      if (filter) {
        navigateToCompanyKpiDrilldown(filter, { replace: true });
      } else {
        clearCompanyKpiDrilldown("jobs");
      }
    });
  });
  scope.querySelectorAll("[data-company-operational-clear]").forEach((btn) => {
    btn.addEventListener("click", () => clearCompanyKpiDrilldown("jobs"));
  });
  const tradeSearch = scope.querySelector("[data-company-trade-search]");
  const tradeOptions = Array.from(
    scope.querySelectorAll("[data-company-trade-filter]"),
  );
  const tradeSelectionSummary = scope.querySelector(
    "[data-company-trade-selection-summary]",
  );
  const updateTradeSelectionSummary = () => {
    if (!tradeSelectionSummary) return;
    const selectedCount = tradeOptions.filter((option) => option.checked).length;
    tradeSelectionSummary.textContent = selectedCount
      ? `${selectedCount} selected`
      : "All trades";
  };
  tradeOptions.forEach((option) =>
    option.addEventListener("change", updateTradeSelectionSummary),
  );
  tradeSearch?.addEventListener("input", () => {
    window.clearTimeout(companyProjectTradeSearchTimer);
    companyProjectTradeSearchTimer = window.setTimeout(() => {
      const query = tradeSearch.value.trim().toLowerCase();
      let visibleCount = 0;
      tradeOptions.forEach((option) => {
        const row = option.closest("label");
        const visible = !query || option.value.toLowerCase().includes(query);
        if (row) row.hidden = !visible;
        if (visible) visibleCount += 1;
      });
      const empty = scope.querySelector("[data-company-trade-empty]");
      if (empty) empty.hidden = visibleCount > 0;
    }, 120);
  });
  const locationFilter = scope.querySelector("[data-company-location-filter]");
  locationFilter?.addEventListener("input", () => {
    window.clearTimeout(companyProjectLocationInputTimer);
    companyProjectLocationInputTimer = window.setTimeout(() => {
      pendingCompanyProjectLocationFilter = locationFilter.value;
    }, 140);
  });
  scope.querySelector("[data-company-filter-apply]")?.addEventListener("click", () => {
    const selectedValues = (attribute) =>
      Array.from(scope.querySelectorAll(`[${attribute}]:checked`)).map(
        (item) => item.value,
      );
    activeCompanyProjectHealthFilters = selectedValues("data-company-health-filter");
    activeCompanyProjectAssignmentFilters = selectedValues(
      "data-company-assignment-filter",
    );
    activeCompanyProjectTradeFilters = selectedValues("data-company-trade-filter");
    window.clearTimeout(companyProjectLocationInputTimer);
    activeCompanyProjectLocationFilter =
      scope.querySelector("[data-company-location-filter]")?.value.trim() || "";
    pendingCompanyProjectLocationFilter = null;
    activeCompanyProjectOpenLabourOnly = !!scope.querySelector(
      "[data-company-open-labour-filter]",
    )?.checked;
    activeCompanyProjectStartFrom =
      scope.querySelector("[data-company-start-from]")?.value || "";
    activeCompanyProjectStartTo =
      scope.querySelector("[data-company-start-to]")?.value || "";
    closeAppPopovers();
    render();
  });
  scope.querySelector("[data-company-filter-clear]")?.addEventListener("click", () => {
    window.clearTimeout(companyProjectTradeSearchTimer);
    window.clearTimeout(companyProjectLocationInputTimer);
    clearCompanyProjectDirectoryFilters();
    closeAppPopovers();
    render();
  });
  scope
    .querySelectorAll("[data-company-project-clear-filters]")
    .forEach((btn) => {
      btn.addEventListener("click", () => {
        clearCompanyProjectDirectoryFilters();
        render();
      });
    });
  scope
    .querySelectorAll("[data-company-project-clear-search]")
    .forEach((btn) => {
      btn.addEventListener("click", () => {
        activeCompanyProjectSearch = "";
        render();
      });
    });
  scope.querySelectorAll("[data-company-status-filter]").forEach((btn) => {
    btn.addEventListener("click", () => {
      activeCompanyProjectStatusFilter = btn.dataset.companyStatusFilter || "all";
      render();
    });
  });
}

// Company panel: agreements awaiting the company's confirmation.
function companyAgreementPanelHTML(user) {
  const pending = (state.agreements || []).filter(
    (a) =>
      a.companyId === user.id && a.status === "pending" && !a.company?.accepted,
  );
  if (!pending.length) return "";
  const rows = pending
    .map(
      (a) => `
    <div class="ch-agr-row">
      <div class="ch-agr-info">
        <div class="ch-agr-title">${escapeHtml(a.terms.workerName)} · ${escapeHtml(a.terms.trade)}</div>
        <div class="ch-agr-meta">${escapeHtml(a.terms.siteName)} · ${a.worker?.accepted ? "Worker signed — your confirmation needed" : "Awaiting both signatures"}</div>
      </div>
      <button class="ch-agr-btn" type="button" data-agr-open="${a.id}">Review &amp; Sign</button>
    </div>`,
    )
    .join("");
  return `
    <div class="ch-agr-panel">
      <div class="ch-agr-panel-head">
        <span class="ch-agr-panel-title">Job Agreements — Action Needed</span>
        <span class="ch-agr-panel-count">${pending.length}</span>
      </div>
      <p class="ch-agr-panel-hint">Bookings stay inactive until you and the worker both sign.</p>
      ${rows}
    </div>`;
}

// ─── Company Account ───────────────────────────────────
function companyTrustProfile(companyId) {
  const jobs = (state.jobs || []).filter((job) => companyOwnsJob(job, companyId));
  const invoices = (state.invoices || []).filter((invoice) => invoice.companyId === companyId);
  const paidInvoices = invoices.filter((invoice) => invoice.status === "paid" || invoice.paidAt);
  const onTimePayments = paidInvoices.filter((invoice) => {
    const paid = dateOnlyMs(invoice.paidAt);
    const due = dateOnlyMs(invoice.dueDate);
    return paid !== null && due !== null && paid <= due;
  });
  const cancellations = (state.cancellations || []).filter((record) => record.companyId === companyId);
  const shortNoticeCancellations = cancellations.filter((record) => {
    const cancelled = dateOnlyMs(record.cancelledAt);
    const start = dateOnlyMs(record.jobStart || record.start || record.startDate);
    if (cancelled === null || start === null) return false;
    return Math.round((start - cancelled) / 86400000) <= PROTECTION_WINDOW_DAYS;
  });
  const completedProjects = jobs.filter((job) => job.completed || job.completedAt);
  const siteInfoComplete = jobs.filter(
    (job) =>
      job.siteAddress &&
      job.siteContact?.name &&
      job.siteContact?.phone &&
      job.arrivalInstructions &&
      job.sitePin,
  );
  const workerSiteIssues = attendanceRecords.filter((record) => {
    const job = findJob(record.jobId);
    return (
      job?.companyId === companyId &&
      (record.disputeStatus === "pending" ||
        record.reportedIssue?.reason ||
        record.lateReport?.reason ||
        record.workerClaimReason)
    );
  });
  const rateChangeFlags = (state.agreements || []).filter((agreement) => {
    if (agreement.companyId !== companyId) return false;
    const job = findJob(agreement.jobId);
    const agreed = Number(agreement.terms?.dayRate || agreement.terms?.workerDayRate || 0);
    const advertised = Number(job?.budgetMax || 0);
    return agreed && advertised && Math.abs(agreed - advertised) > 0;
  });
  const historyCount =
    paidInvoices.length +
    cancellations.length +
    completedProjects.length +
    workerSiteIssues.length +
    rateChangeFlags.length;
  const positive = [];
  const improvement = [];
  if (paidInvoices.length) {
    positive.push(`${onTimePayments.length}/${paidInvoices.length} invoices paid on or before due date`);
    if (onTimePayments.length < paidInvoices.length) improvement.push(`${paidInvoices.length - onTimePayments.length} invoice payment${paidInvoices.length - onTimePayments.length === 1 ? "" : "s"} paid after due date`);
  }
  if (completedProjects.length) positive.push(`${completedProjects.length} confirmed completed project${completedProjects.length === 1 ? "" : "s"}`);
  if (jobs.length) positive.push(`${siteInfoComplete.length}/${jobs.length} projects have complete core site information`);
  if (shortNoticeCancellations.length) improvement.push(`${shortNoticeCancellations.length} short-notice cancellation${shortNoticeCancellations.length === 1 ? "" : "s"} recorded`);
  if (workerSiteIssues.length) improvement.push(`${workerSiteIssues.length} worker-reported site or attendance issue${workerSiteIssues.length === 1 ? "" : "s"} recorded`);
  if (rateChangeFlags.length) improvement.push(`${rateChangeFlags.length} rate difference${rateChangeFlags.length === 1 ? "" : "s"} detected between advertised and agreed records`);
  return {
    status: historyCount < 5 ? "New / Insufficient history" : improvement.length ? "Areas requiring improvement" : "Positive operational indicators",
    historyCount,
    positive,
    improvement,
    evidence: {
      paidInvoices: paidInvoices.length,
      onTimePayments: onTimePayments.length,
      shortNoticeCancellations: shortNoticeCancellations.length,
      siteInfoComplete: siteInfoComplete.length,
      totalProjects: jobs.length,
      completedProjects: completedProjects.length,
      workerSiteIssues: workerSiteIssues.length,
      rateChangeFlags: rateChangeFlags.length,
    },
  };
}

function companyTrustProfileHTML(companyId, { workerView = false } = {}) {
  const profile = companyTrustProfile(companyId);
  const positives = profile.positive.length
    ? profile.positive.map((item) => `<li>${escapeHtml(item)}</li>`).join("")
    : `<li>More verified project history is needed before positive indicators are shown.</li>`;
  const improvements = profile.improvement.length
    ? profile.improvement.map((item) => `<li>${escapeHtml(item)}</li>`).join("")
    : `<li>No evidence-based improvement areas currently recorded.</li>`;
  return `<div class="company-trust-card${workerView ? " worker-view" : ""}">
    <div class="company-trust-head">
      <div>
        <p class="company-home-kicker">COMPANY RELIABILITY</p>
        <h3>${escapeHtml(profile.status)}</h3>
      </div>
      <span>${profile.historyCount} evidence item${profile.historyCount === 1 ? "" : "s"}</span>
    </div>
    <div class="company-trust-grid">
      <div>
        <strong>Positive operational indicators</strong>
        <ul>${positives}</ul>
      </div>
      <div>
        <strong>Areas requiring improvement</strong>
        <ul>${improvements}</ul>
      </div>
    </div>
    <p class="company-trust-note">${workerView ? "Shown to workers as evidence-based trust context. No final company score is displayed." : "Evidence is based on OnSite operational records. No public star rating or final company score is generated."}</p>
  </div>`;
}

